    /// Band 1 — every enabled Agent as a horizontally scrolling logo strip.
    /// Tapping a logo moves the draft to that Agent's first available option,
    /// which re-scopes the model list below; the active logo wears an accent
    /// bar on the strip's bottom hairline and stays scrolled into view.
    fn render_runtime_agent_strip(
        &self,
        catalog: Option<&SessionRuntimeOptionCatalog>,
        draft: Option<&SessionRuntimeSelection>,
        busy: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let agents = self.runtime_agent_strip_agents(catalog);
        let draft_agent = draft.map(|draft| draft.agent_id.clone());
        div()
            .flex_shrink_0()
            .border_b_1()
            .border_color(theme::border_subtle())
            .child(
                div()
                    .id("runtime-agent-strip")
                    .h(px(RUNTIME_SHEET_AGENT_STRIP_HEIGHT))
                    .overflow_x_scroll()
                    .restrict_scroll_to_axis()
                    .track_scroll(&self.runtime_agent_strip_scroll)
                    .flex()
                    .items_center()
                    .gap_1()
                    .px_2()
                    .children(agents.into_iter().map(|(agent_id, label)| {
                        let selected = draft_agent.as_ref() == Some(&agent_id);
                        let tab_agent_id = agent_id.clone();
                        div()
                            .id(format!("runtime-agent-tab:{}", agent_id.as_str()))
                            .relative()
                            .flex_shrink_0()
                            .w(px(40.0))
                            .h(px(40.0))
                            .rounded(px(theme::RADIUS_CONTROL))
                            .flex()
                            .items_center()
                            .justify_center()
                            .when(selected, |tab| tab.bg(theme::bg_card_dim()))
                            .when(!busy, |tab| {
                                tab.cursor_pointer()
                                    .active(|style| style.bg(theme::row_pressed_bg()))
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(move |this, _, _, cx| {
                                            this.choose_runtime_agent(tab_agent_id.clone(), cx)
                                        }),
                                    )
                            })
                            .child(runtime_agent_icon(
                                &agent_id,
                                &label,
                                px(18.0),
                                if selected {
                                    theme::text_primary()
                                } else {
                                    theme::text_secondary()
                                },
                            ))
                            .when(selected, |tab| tab.child(runtime_tab_indicator()))
                    })),
            )
            .into_any_element()
    }

    /// The strip's tabs in display order: catalog-available Agents labelled
    /// with the desktop's snapshots, ordered like the desktop runtime menus
    /// (`order_index`, then label, then id). A snapshot that has not landed
    /// yet falls back to the label ordering.
    fn runtime_agent_strip_agents(
        &self,
        catalog: Option<&SessionRuntimeOptionCatalog>,
    ) -> Vec<(AgentId, String)> {
        let Some(catalog) = catalog else {
            return Vec::new();
        };
        let mut agents: Vec<(AgentId, String)> = Vec::new();
        for option in &catalog.options {
            if option.availability != RuntimeOptionAvailability::Available {
                continue;
            }
            let agent_id = &option.selection.agent_id;
            if agents.iter().any(|(existing, _)| existing == agent_id) {
                continue;
            }
            let label = self
                .runtime_agent_labels
                .get(agent_id)
                .cloned()
                .unwrap_or_else(|| option.agent_label.clone());
            agents.push((agent_id.clone(), label));
        }
        agents.sort_by(|(left_id, left_label), (right_id, right_label)| {
            let left_rank = self
                .runtime_agent_order
                .iter()
                .position(|id| id == left_id)
                .unwrap_or(usize::MAX);
            let right_rank = self
                .runtime_agent_order
                .iter()
                .position(|id| id == right_id)
                .unwrap_or(usize::MAX);
            left_rank
                .cmp(&right_rank)
                .then_with(|| left_label.cmp(right_label))
                .then_with(|| left_id.cmp(right_id))
        });
        agents
    }

    /// Scrolls the Agent strip so the draft Agent's logo is visible. Safe to
    /// call before the strip's first paint: the scroll handle defers the
    /// anchor until the tab's bounds exist and then applies it once.
    fn anchor_runtime_agent_strip(&mut self) {
        let catalog = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.runtime_options.value.as_ref());
        let agents = self.runtime_agent_strip_agents(catalog);
        let Some(index) = self.runtime_draft.as_ref().and_then(|draft| {
            agents
                .iter()
                .position(|(agent_id, _)| agent_id == &draft.agent_id)
        }) else {
            return;
        };
        self.runtime_agent_strip_scroll.scroll_to_item(index);
    }

    /// Band 2 — the full-bleed search row. The query filters provider labels
    /// and model labels inside the band below; it never leaves the selected
    /// Agent when the strip switches.
    fn render_runtime_search_row(&self) -> gpui::AnyElement {
        div()
            .flex_shrink_0()
            .h(px(RUNTIME_SHEET_SEARCH_HEIGHT))
            .border_b_1()
            .border_color(theme::border_subtle())
            .px_3()
            .flex()
            .items_center()
            .gap_2()
            .child(
                svg()
                    .path("icons/search.svg")
                    .size(px(theme::ICON_SM))
                    .flex_shrink_0()
                    .text_color(theme::text_muted()),
            )
            .when_some(self.runtime_sheet_search.clone(), |row, input| {
                // The row already draws the band's divider and background, so
                // the kit input contributes only the text surface and its
                // editing behavior (selection, IME, and the soft keyboard).
                row.child(
                    div()
                        .flex_1()
                        .min_w_0()
                        .on_mouse_down(MouseButton::Left, resume_keyboard_on_tap)
                        .child(Input::new(&input).appearance(false)),
                )
            })
            .into_any_element()
    }

    /// Band 3 — provider-grouped model list for the selected Agent, at a
    /// fixed height so the bands above and below stay put; a long catalog
    /// scrolls inside this band. Rows keep the desktop model brand icons.
    fn render_runtime_model_list(
        &self,
        catalog: Option<&SessionRuntimeOptionCatalog>,
        draft: Option<&SessionRuntimeSelection>,
        busy: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let query = self
            .runtime_sheet_search
            .as_ref()
            .map(|input| input.read(cx).value().trim().to_lowercase())
            .unwrap_or_default();
        let Some((catalog, draft)) = catalog.zip(draft) else {
            return div()
                .flex_shrink_0()
                .h(px(RUNTIME_SHEET_MODEL_LIST_HEIGHT))
                .border_b_1()
                .border_color(theme::border_subtle())
                .p_4()
                .text_size(theme::font_caption())
                .text_color(theme::text_muted())
                .child(locale::text(
                    "Loading session settings...",
                    "正在加载会话设置…",
                    "正在載入工作階段設定…",
                ))
                .into_any_element();
        };
        let agent_id = draft.agent_id.clone();

        let mut sources = catalog
            .auth_sources
            .iter()
            .filter(|source| source.agent_id == agent_id)
            .cloned()
            .collect::<Vec<_>>();
        sources.sort_by(|left, right| {
            left.kind
                .cmp(&right.kind)
                .then_with(|| left.label.cmp(&right.label))
                .then_with(|| left.source.cmp(&right.source))
        });

        let mut groups = Vec::new();
        for source in sources {
            let options = catalog
                .options
                .iter()
                .filter(|option| {
                    option.availability == RuntimeOptionAvailability::Available
                        && option.selection.agent_id == agent_id
                        && option.selection.auth_source == source.source
                })
                .cloned()
                .collect::<Vec<_>>();
            let source_matches = query.is_empty()
                || source.label.to_lowercase().contains(&query)
                || runtime_auth_source_display_label(&source)
                    .to_lowercase()
                    .contains(&query);
            let models = options
                .iter()
                .filter(|option| {
                    source_matches || option.model_label.to_lowercase().contains(&query)
                })
                .cloned()
                .collect::<Vec<_>>();
            if !source_matches && models.is_empty() {
                continue;
            }

            let status = runtime_auth_source_status_label(
                source.availability,
                models.len().max(options.len()),
            );
            let source_id = source.source.id().to_string();
            let (heading_icon, heading_color) = match source.kind {
                RuntimeAuthSourceKind::ProviderProfile => {
                    ("icons/database.svg", theme::accent_green())
                }
                RuntimeAuthSourceKind::AgentAccount => ("icons/user.svg", theme::accent_chart3()),
            };
            let group = div()
                .child(
                    div()
                        .h(px(34.0))
                        .px_4()
                        .flex()
                        .items_center()
                        .gap_2()
                        .child(
                            svg()
                                .path(heading_icon)
                                .size(px(15.0))
                                .text_color(heading_color),
                        )
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .overflow_hidden()
                                .text_ellipsis()
                                .whitespace_nowrap()
                                .text_size(theme::font_caption())
                                .font_weight(FontWeight::SEMIBOLD)
                                .text_color(theme::sidebar_foreground(0.84))
                                .child(runtime_auth_source_display_label(&source)),
                        )
                        .child(
                            div()
                                .flex_shrink_0()
                                .text_size(theme::font_micro())
                                .text_color(theme::text_muted())
                                .child(status),
                        ),
                )
                .children(models.into_iter().map(|option| {
                    let selection = option.selection.clone();
                    let is_selected = runtime_option_matches(&option, draft);
                    let model_id = selection.model_id().map(str::to_string);
                    let row_id = format!(
                        "runtime-model:{}:{}",
                        source_id,
                        runtime_model_selection_key(&selection.model)
                    );
                    runtime_sheet_row(
                        row_id,
                        runtime_model_icon(
                            model_id.as_deref(),
                            px(theme::ICON_SM + 2.0),
                            theme::text_primary(),
                        ),
                        option.model_label.clone(),
                        is_selected,
                        false,
                    )
                    .pl(px(28.0))
                    .pr_3()
                    .when(!busy, |row| {
                        row.cursor_pointer()
                            .active(|style| style.bg(theme::row_active_bg()))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener({
                                    let selection = selection.clone();
                                    move |this, _, _, cx| {
                                        this.choose_runtime_selection(selection.clone(), cx)
                                    }
                                }),
                            )
                    })
                    .when(is_selected, |row| {
                        row.child(
                            svg()
                                .path("icons/check.svg")
                                .size(px(theme::ICON_SM))
                                .text_color(theme::text_primary()),
                        )
                    })
                }));
            groups.push(group);
        }

        div()
            .id("runtime-model-list")
            .flex_shrink_0()
            .h(px(RUNTIME_SHEET_MODEL_LIST_HEIGHT))
            .overflow_y_scroll()
            .restrict_scroll_to_axis()
            .border_b_1()
            .border_color(theme::border_subtle())
            .pb_1()
            .when(groups.is_empty(), |list| {
                list.child(
                    div()
                        .px_4()
                        .py(px(28.0))
                        .text_size(theme::font_caption())
                        .text_color(theme::text_muted())
                        .child(if query.is_empty() {
                            locale::text("No configuration", "暂无配置", "暫無配置")
                        } else {
                            locale::text("No models found", "未找到模型", "找不到模型")
                        }),
                )
            })
            .children(groups)
            .into_any_element()
    }

    /// Band 4 — everything beyond Agent and model: reasoning effort, mode and
    /// per-model session options. The band fills the card's remaining height
    /// and scrolls on its own.
    #[allow(clippy::too_many_arguments)]
    fn render_runtime_options_list(
        &self,
        catalog: Option<&SessionRuntimeOptionCatalog>,
        draft: Option<&SessionRuntimeSelection>,
        reasoning_efforts: Vec<RuntimeCascadeChoice>,
        modes: Vec<RuntimeCascadeChoice>,
        features: Vec<SessionRuntimeFeature>,
        selection_available: bool,
        busy: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let mut list = div()
            .id("runtime-options-list")
            .flex_1()
            .min_h_0()
            .overflow_y_scroll()
            .restrict_scroll_to_axis()
            .pb_2();
        let Some(draft) = draft else {
            return list.into_any_element();
        };
        list = list
            .when(catalog.is_some() && !selection_available, |list| {
                list.child(
                    div()
                        .mx_3()
                        .mt_3()
                        .rounded(px(theme::RADIUS_CONTROL))
                        .border_1()
                        .border_color(theme::accent_yellow())
                        .bg(theme::bg_card_dim())
                        .p_3()
                        .text_size(theme::font_caption())
                        .text_color(theme::accent_yellow())
                        .child(locale::text(
                            "The current session settings are unavailable. Select an available option.",
                            "当前会话设置不可用，请选择一个可用选项。",
                            "目前工作階段設定無法使用，請選擇可用選項。",
                        )),
                )
            })
            .when(!reasoning_efforts.is_empty(), |list| {
                list.child(runtime_section_heading(locale::common("Reasoning")))
                    .child(
                        div()
                            .px_3()
                            .flex()
                            .flex_wrap()
                            .gap_2()
                            .child(
                                runtime_choice_button(
                                    "runtime-reasoning:default",
                                    locale::common("Default"),
                                    draft.reasoning_effort.is_none(),
                                )
                                .when(!busy, |button| {
                                    button
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(|this, _, _, cx| {
                                                this.choose_default_runtime_reasoning(cx)
                                            }),
                                        )
                                }),
                            )
                            .children(reasoning_efforts.into_iter().map(|choice| {
                                let selected = draft.reasoning_effort.as_deref()
                                    == Some(choice.value.as_str());
                                self.render_runtime_choice("reasoning", choice, selected, cx)
                            })),
                    )
            })
            .when(!modes.is_empty(), |list| {
                list.child(runtime_section_heading(locale::common("Mode")))
                    .child(
                        div()
                            .px_3()
                            .flex()
                            .flex_wrap()
                            .gap_2()
                            .child(
                                runtime_choice_button(
                                    "runtime-mode:default",
                                    locale::common("Default"),
                                    draft.mode_id.is_none(),
                                )
                                .when(!busy, |button| {
                                    button
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(|this, _, _, cx| {
                                                this.choose_default_runtime_mode(cx)
                                            }),
                                        )
                                }),
                            )
                            .children(modes.into_iter().map(|choice| {
                                let selected =
                                    draft.mode_id.as_deref() == Some(choice.value.as_str());
                                self.render_runtime_choice("mode", choice, selected, cx)
                            })),
                    )
            })
            .when(!features.is_empty(), |list| {
                list.child(runtime_section_heading(locale::common("Session options")))
                    .children(
                        features
                            .into_iter()
                            .map(|feature| self.render_runtime_feature(feature, cx)),
                    )
            });
        list.into_any_element()
    }
    fn render_runtime_choice(
        &self,
        group: &'static str,
        choice: RuntimeCascadeChoice,
        selected: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let selection = choice.selection;
        runtime_choice_button(
            format!("runtime-{group}:{}", choice.value),
            choice.label,
            selected,
        )
        .when(self.runtime_switch_busy_generation.is_none(), |button| {
            button
                .cursor_pointer()
                .active(|style| style.bg(theme::row_pressed_bg()))
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, _, _, cx| {
                        this.choose_runtime_selection(selection.clone(), cx)
                    }),
                )
        })
        .into_any_element()
    }

    fn render_runtime_feature(
        &self,
        feature: SessionRuntimeFeature,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let feature_id = feature.id.clone();
        let selected_value = self
            .runtime_draft
            .as_ref()
            .and_then(|draft| draft.config_values.get(&feature_id))
            .cloned();
        let choices = match feature.kind {
            SessionRuntimeFeatureKind::Toggle => vec![
                (locale::common("Default").to_string(), None),
                (locale::common("On").to_string(), Some("true".to_string())),
                (locale::common("Off").to_string(), Some("false".to_string())),
            ],
            SessionRuntimeFeatureKind::Select => {
                std::iter::once((locale::common("Default").to_string(), None))
                    .chain(feature.values.iter().map(|value| {
                        (
                            value.label.clone().unwrap_or_else(|| value.value.clone()),
                            Some(value.value.clone()),
                        )
                    }))
                    .collect()
            }
            SessionRuntimeFeatureKind::String => Vec::new(),
        };
        let row = div()
            .px_3()
            .pb_3()
            .flex()
            .flex_col()
            .gap_2()
            .child(
                div()
                    .text_size(theme::font_caption())
                    .text_color(theme::text_secondary())
                    .child(feature.label.clone()),
            )
            .when_some(feature.description.clone(), |row, description| {
                row.child(
                    div()
                        .text_size(theme::font_micro())
                        .text_color(theme::text_muted())
                        .child(description),
                )
            });
        if feature.kind == SessionRuntimeFeatureKind::String {
            return match self.runtime_feature_inputs.get(&feature_id) {
                Some(input) => row.child(runtime_feature_input(input)).into_any_element(),
                None => row
                    .child(
                        div()
                            .text_size(theme::font_micro())
                            .text_color(theme::text_muted())
                            .child(locale::common("Loading value...")),
                    )
                    .into_any_element(),
            };
        }
        row.child(
            div()
                .flex()
                .flex_wrap()
                .gap_2()
                .children(
                    choices
                        .into_iter()
                        .enumerate()
                        .map(|(index, (label, value))| {
                            let selected = selected_value == value;
                            let selected_feature_id = feature_id.clone();
                            let selected_value = value.clone();
                            runtime_choice_button(
                                format!("runtime-feature:{feature_id}:{index}"),
                                label,
                                selected,
                            )
                            .when(
                                self.runtime_switch_busy_generation.is_none(),
                                |button| {
                                    button
                                        .cursor_pointer()
                                        .active(|style| style.bg(theme::row_pressed_bg()))
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(move |this, _, _, cx| {
                                                this.choose_runtime_feature(
                                                    selected_feature_id.clone(),
                                                    selected_value.clone(),
                                                    cx,
                                                )
                                            }),
                                        )
                                },
                            )
                        }),
                ),
        )
        .into_any_element()
    }

    fn render_header(
        &self,
        title: &str,
        state: Option<AgentSessionState>,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        // A state the user has to act on is named, not just tinted: the phone
        // used to draw a 6px dot and leave the reader to guess which of the
        // session states it stood for.
        let (status_color, status_label) = match state {
            Some(AgentSessionState::Running) => {
                (theme::accent_success(), locale::common("Running"))
            }
            Some(AgentSessionState::NeedsInput) => (
                theme::accent_yellow(),
                locale::text("Needs you", "需要你操作", "需要你操作"),
            ),
            Some(AgentSessionState::Error) => (theme::accent_red(), locale::common("Failed")),
            Some(AgentSessionState::Idle) => (theme::text_muted(), locale::common("Idle")),
            Some(AgentSessionState::Archived) => (theme::text_muted(), locale::common("Archived")),
            Some(_) => (theme::text_muted(), locale::common("Closed")),
            None => (theme::accent_yellow(), locale::common("No session")),
        };
        let (badge, terminal_running) = self
            .workbench
            .as_ref()
            .map(|workbench| {
                let workbench = workbench.read(cx);
                (
                    workbench.right_rail_badge(),
                    workbench.terminal_is_running(),
                )
            })
            .unwrap_or((0, false));
        div()
            .h(px(theme::HEADER_HEIGHT))
            .flex_shrink_0()
            .border_b_1()
            .border_color(theme::border_subtle())
            .flex()
            .items_center()
            .child(
                div()
                    .id("open-session-drawer")
                    .size(px(theme::HEADER_BUTTON_SIZE))
                    .flex_shrink_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .cursor_pointer()
                    .aria_label(locale::text("Sessions", "会话", "會話"))
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .on_mouse_up(MouseButton::Left, cx.listener(Self::toggle_drawer))
                    .child(
                        svg()
                            .path("icons/menu.svg")
                            .size(px(theme::ICON_MD))
                            .text_color(theme::text_secondary()),
                    ),
            )
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .justify_center()
                    .items_center()
                    .child(
                        div()
                            .max_w_full()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_detail())
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(theme::text_primary())
                            .child(title.to_string()),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(theme::SPACING_XS))
                            .child(
                                div()
                                    .size(px(theme::ICON_STATUS))
                                    .flex_shrink_0()
                                    .rounded_full()
                                    .bg(status_color),
                            )
                            .child(
                                div()
                                    .text_size(theme::font_micro())
                                    .text_color(status_color)
                                    .child(status_label),
                            ),
                    ),
            )
            .child(
                div()
                    .id("refresh-session")
                    .size(px(theme::HEADER_BUTTON_SIZE))
                    .flex_shrink_0()
                    .flex()
                    .items_center()
                    .justify_center()
                    .cursor_pointer()
                    .aria_label(locale::common("Refresh"))
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .on_mouse_up(MouseButton::Left, cx.listener(Self::refresh))
                    .child(
                        svg()
                            .path("icons/refresh.svg")
                            .size(px(theme::ICON_SM))
                            .text_color(theme::text_muted()),
                    ),
            )
            .when(
                self.team_controller
                    .as_ref()
                    .is_some_and(|team| team.is_supported()),
                |header| {
                    header.child(
                        Button::new("open-team")
                            .ghost()
                            .h(px(theme::HEADER_BUTTON_SIZE))
                            .label(locale::text("Team…", "团队…", "團隊…"))
                            .on_click(
                                cx.listener(|this, _, window, cx| this.open_team(window, cx)),
                            ),
                    )
                },
            )
            // The right rail's only entry point. It was reachable exclusively
            // from an unhinted swipe; a phone user has no reason to discover
            // that a screen with Files, Git, and a terminal exists at all.
            .child(
                div()
                    .id("open-right-rail")
                    .size(px(theme::HEADER_BUTTON_SIZE))
                    .flex_shrink_0()
                    .relative()
                    .flex()
                    .items_center()
                    .justify_center()
                    .cursor_pointer()
                    .aria_label(locale::text(
                        "Files, Git, and terminal",
                        "文件、Git 与终端",
                        "檔案、Git 與終端機",
                    ))
                    .active(|style| style.bg(theme::row_pressed_bg()))
                    .on_mouse_up(MouseButton::Left, cx.listener(Self::toggle_right_rail))
                    .child(
                        svg()
                            .path("icons/panel-right.svg")
                            .size(px(theme::ICON_MD))
                            .text_color(if terminal_running || badge > 0 {
                                theme::text_primary()
                            } else {
                                theme::text_secondary()
                            }),
                    )
                    .when(badge > 0, |button| {
                        button.child(
                            div()
                                .absolute()
                                .top(px(8.0))
                                .right(px(6.0))
                                .min_w(px(16.0))
                                .h(px(16.0))
                                .px(px(3.0))
                                .rounded_full()
                                .bg(theme::accent_blue())
                                .flex()
                                .items_center()
                                .justify_center()
                                .text_size(theme::font_micro())
                                .text_color(theme::bg_primary())
                                .child(badge.min(99).to_string()),
                        )
                    })
                    .when(terminal_running && badge == 0, |button| {
                        button.child(
                            div()
                                .absolute()
                                .top(px(10.0))
                                .right(px(10.0))
                                .size(px(8.0))
                                .rounded_full()
                                .bg(theme::accent_success()),
                        )
                    }),
            )
    }

    /// The open session's group as a tab strip.
    ///
    /// Desktop renders a group as side-by-side panes. A phone cannot show two
    /// conversations at once, so the same membership becomes tabs: the desktop
    /// grouping survives, the split layout does not.
    fn render_session_group_tabs(
        &self,
        name: &str,
        members: &[(VibexSessionId, String, AgentSessionState)],
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let selected = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.selected_session_id.clone());
        div()
            .id("mobile-session-group-tabs")
            .flex_shrink_0()
            .border_b_1()
            .border_color(theme::border_subtle())
            .flex()
            .flex_col()
            .child(
                div()
                    .px(px(theme::SPACING_MD))
                    .pt(px(theme::SPACING_SM))
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_XS))
                    .child(
                        svg()
                            .path("icons/layers.svg")
                            .size(px(12.0))
                            .text_color(theme::accent_purple()),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_micro())
                            .text_color(theme::text_muted())
                            .child(name.to_string()),
                    ),
            )
            .child(
                div()
                    .id("mobile-session-group-tabs-scroll")
                    .overflow_x_scroll()
                    .restrict_scroll_to_axis()
                    .flex()
                    .items_center()
                    .gap(px(theme::SPACING_XS))
                    .px(px(theme::SPACING_MD))
                    .py(px(theme::SPACING_SM))
                    .children(members.iter().map(|(session_id, title, state)| {
                        let active = selected.as_ref() == Some(session_id);
                        let open_id = session_id.clone();
                        div()
                            .id(format!("session-group-tab:{}", session_id.as_str()))
                            .flex_shrink_0()
                            .max_w(px(180.0))
                            .h(px(36.0))
                            .px(px(theme::SPACING_MD))
                            .rounded_full()
                            .border_1()
                            .border_color(if active {
                                theme::accent_purple()
                            } else {
                                theme::border_subtle()
                            })
                            .bg(if active {
                                theme::accent_purple().opacity(0.14)
                            } else {
                                theme::bg_card()
                            })
                            .flex()
                            .items_center()
                            .gap(px(theme::SPACING_XS))
                            .cursor_pointer()
                            .aria_label(title.clone())
                            .active(|style| style.bg(theme::row_pressed_bg()))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(move |this, _, _, cx| {
                                    this.open_session(open_id.clone(), cx)
                                }),
                            )
                            .child(
                                div()
                                    .size(px(6.0))
                                    .flex_shrink_0()
                                    .rounded_full()
                                    .bg(session_state_color(*state)),
                            )
                            .child(
                                div()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .whitespace_nowrap()
                                    .text_size(theme::font_caption())
                                    .text_color(if active {
                                        theme::text_primary()
                                    } else {
                                        theme::text_secondary()
                                    })
                                    .child(title.clone()),
                            )
                    })),
            )
            .into_any_element()
    }

    fn render_turn(
        &self,
        turn: &TimelineConversationTurn,
        is_first: bool,
        is_last: bool,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let expanded = self.timeline_process_expanded(turn);
        let display_settings = self.effective_timeline_display_settings();
        let conclusion_row = turn
            .conclusion_row
            .as_ref()
            .filter(|row| !row.body.trim().is_empty());
        div()
            .id(format!("timeline-turn:{}", turn.id))
            .w_full()
            .min_w_0()
            .flex()
            .flex_col()
            // One rhythm for every child used to flatten the turn: the user
            // message, the activity stream, and the answer all sat 12px apart.
            // The grouping gaps below give the answer the weight it has on the
            // desktop without inventing a second layout.
            .gap(px(theme::SPACING_SM))
            // A turn is a unit, so the separation between turns is clearly
            // larger than any gap inside one. The list item already carries
            // `pb`, so only the leading edge is added here.
            .when(!is_first, |turn| turn.pt(px(theme::SPACING_LG)))
            .when_some(turn.user_row.as_ref(), |container, row| {
                container.child(self.render_user_message_row(row, is_last, turn.complete, cx))
            })
            .when(!turn.process_rows.is_empty(), |container| {
                container.child(
                    div()
                        .pt(px(theme::SPACING_SM))
                        .child(self.render_turn_process_header(turn, expanded, cx)),
                )
            })
            .when(expanded && !turn.process_rows.is_empty(), |container| {
                container.child(
                    div().flex().flex_col().gap(px(2.0)).child(
                        div()
                            .flex()
                            .flex_col()
                            .children(self.render_timeline_process_rows(turn, cx)),
                    ),
                )
            })
            .when_some(conclusion_row, |container, row| {
                // The answer gets air above it and a left rail, so it reads as
                // the point of the turn instead of the next process line.
                container.child(
                    div()
                        .mt(px(theme::SPACING_SM))
                        .pl(px(theme::SPACING_SM))
                        .border_l_2()
                        .border_color(theme::border_default())
                        .child(self.render_timeline_row(turn, row, true, cx)),
                )
            })
            .when_some(
                self.render_turn_file_changes_card(turn, cx),
                |container, card| container.child(card),
            )
            .when(
                conclusion_row.is_none()
                    && !(turn.complete || turn.superseded)
                    && !turn.process_rows.iter().any(|row| {
                        row.kind == TimelineRowKind::Reasoning && self.reasoning_live(row)
                    }),
                |container| {
                    if display_settings.reasoning_display_mode
                        == AgentTimelineReasoningDisplayMode::LatestAtBottom
                        && let Some(reasoning) = turn.live_status.as_deref()
                    {
                        return container.child(self.render_live_reasoning(turn, reasoning, cx));
                    }
                    if !display_settings.show_agent_generation_status {
                        return container;
                    }
                    // Desktop parity: pending permission replaces the progress
                    // label with the waiting-for-confirmation string, then the
                    // label is projected through the bounded markdown summary
                    // (`agent_progress_label`).
                    let pending_label = if turn.pending_permission {
                        locale::text(
                            "Waiting for confirmation...",
                            "等待确认中...",
                            "等待確認中...",
                        )
                        .to_string()
                    } else {
                        turn.live_status
                            .as_deref()
                            .unwrap_or(locale::text("Thinking...", "思考中...", "思考中..."))
                            .to_string()
                    };
                    container.child(render_mobile_thinking_indicator(
                        &turn.id,
                        &agent_progress_label(&pending_label),
                    ))
                },
            )
            .into_any_element()
    }

    fn render_live_reasoning(
        &self,
        turn: &TimelineConversationTurn,
        body: &str,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let row = TimelineRow {
            id: format!("reasoning-live:{}", turn.id),
            kind: TimelineRowKind::Reasoning,
            item_ids: Vec::new(),
            turn_id: Some(turn.id.clone()),
            turn_item_count: turn.item_count,
            turn_failed: turn.failed,
            turn_pending_permission: turn.pending_permission,
            conclusion: false,
            first_sequence: 0,
            last_sequence: 0,
            // A thought still arriving is drawn from the live stream, which
            // carries no item of its own to be stamped with.
            timestamp_ms: 0,
            title: locale::common("Reasoning").to_string(),
            body: body.to_string(),
            streaming: true,
            collapsible: true,
            pending_permission: turn.pending_permission,
            failed: turn.failed,
            runtime_attribution: turn.runtime_attribution.clone(),
            file_path: None,
        };
        self.render_thought_process_row(&row, cx)
    }

    /// The newest item a row draws.
    ///
    /// A row aggregates items and carries its own bounds; the newest one is
    /// what the row renders. `last_sequence` is the fast path, and the id check
    /// keeps a compacted row from claiming an item that merely reuses the
    /// sequence it ended on.
    fn timeline_row_item(&self, row: &TimelineRow) -> Option<&TimelineItem> {
        let items = &self.controller.as_ref()?.state.timeline.items;
        // Authoritative history and streamed inserts are sequence-sorted.
        // Summarizing a long activity group must not scan the entire history
        // again for each member.
        if let Ok(index) = items.binary_search_by_key(&row.last_sequence, |item| item.sequence)
            && row.item_ids.iter().any(|id| id == items[index].id.as_str())
        {
            return Some(&items[index]);
        }
        items
            .iter()
            .filter(|item| row.item_ids.iter().any(|id| id == item.id.as_str()))
            .max_by_key(|item| item.sequence)
    }

    fn timeline_row_latest_payload(&self, row: &TimelineRow) -> Option<&TimelinePayload> {
        self.timeline_row_item(row).map(|item| &item.payload)
    }

    fn timeline_row_user_attachments(&self, row: &TimelineRow) -> Vec<MessageAttachment> {
        if let Some(TimelinePayload::UserMessage(message)) = self.timeline_row_latest_payload(row) {
            return message.attachments.clone();
        }
        self.pending_user_message
            .as_ref()
            .filter(|pending| {
                row.item_ids
                    .iter()
                    .any(|item_id| item_id == pending.item_id.as_str())
            })
            .map(|pending| pending.attachments.clone())
            .unwrap_or_default()
    }

    fn toggle_timeline_metadata_tip(&mut self, tip: TimelineMetadataTip, cx: &mut Context<Self>) {
        if self.timeline_metadata_tip.as_ref() == Some(&tip) {
            self.timeline_metadata_tip = None;
        } else {
            self.timeline_metadata_tip = Some(tip);
        }
        cx.notify();
    }

    fn open_user_attachment(
        &mut self,
        attachment: MessageAttachment,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !message_attachment_is_image(&attachment) {
            self.open_user_attachment_file(attachment, window, cx);
            return;
        }
        if let Some((format, bytes)) = decode_message_attachment_data_uri(&attachment) {
            self.attachment_preview = Some(MobileAttachmentPreview {
                label: attachment.label.clone(),
                image: Arc::new(Image::from_bytes(format, bytes)),
                zoom: 1.0,
                offset: point(px(0.0), px(0.0)),
                pan: None,
            });
            self.attachment_preview_loading = None;
            cx.notify();
            return;
        }
        let Some((workspace_id, workspace_root)) = self.active_workspace_context() else {
            self.fail(BackendError::failed(
                "mobile_attachment_workspace_missing",
                locale::text(
                    "The attachment workspace is not available.",
                    "附件所在工作区不可用。",
                    "附件所在工作區無法使用。",
                ),
            ));
            cx.notify();
            return;
        };
        let Some(path) = message_attachment_workspace_path(
            attachment.uri.as_deref().unwrap_or_default(),
            Some(&workspace_root),
        ) else {
            self.open_user_attachment_file(attachment, window, cx);
            return;
        };
        let Some(format) = message_attachment_image_format(&attachment) else {
            self.open_user_attachment_file(attachment, window, cx);
            return;
        };
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let label = if attachment.label.trim().is_empty() {
            locale::text("Image", "图片", "圖片").to_string()
        } else {
            attachment.label.clone()
        };
        self.attachment_preview_loading = Some(label.clone());
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend.download_file(workspace_id, path).await
        });
        let task = cx.spawn(async move |entity: WeakEntity<Self>, cx| {
            let outcome = flatten_join(runner.await);
            let _ = entity.update(cx, |this, cx| {
                this.attachment_preview_loading = None;
                match outcome {
                    Ok(bytes) => {
                        this.attachment_preview = Some(MobileAttachmentPreview {
                            label: label.clone(),
                            image: Arc::new(Image::from_bytes(format, bytes)),
                            zoom: 1.0,
                            offset: point(px(0.0), px(0.0)),
                            pan: None,
                        });
                    }
                    Err(error) => this.fail(error),
                }
                cx.notify();
            });
        });
        self.tasks.push(task);
    }

    fn open_user_attachment_file(
        &mut self,
        attachment: MessageAttachment,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some((workspace_id, workspace_root)) = self.active_workspace_context() else {
            return;
        };
        let Some(path) = message_attachment_workspace_path(
            attachment.uri.as_deref().unwrap_or_default(),
            Some(&workspace_root),
        ) else {
            self.fail(BackendError::failed(
                "mobile_attachment_path_invalid",
                locale::text(
                    "This attachment cannot be opened from the workspace.",
                    "无法从工作区打开此附件。",
                    "無法從工作區開啟此附件。",
                ),
            ));
            cx.notify();
            return;
        };
        self.pending_workbench_surface = Some(WorkbenchSurface::Files);
        self.ensure_workbench(workspace_id, cx);
        if let Some(workbench) = self.workbench.as_ref() {
            workbench.update(cx, |workbench, cx| {
                workbench.set_surface(WorkbenchSurface::Files, cx);
                workbench.open_file(path.clone(), cx);
            });
        }
        self.start_drawer_snap(DrawerPage::Workbench.open_offset(), Some(window), cx);
    }

    fn active_workspace_context(&self) -> Option<(vibex_core::WorkspaceId, String)> {
        let session = self
            .controller
            .as_ref()?
            .state
            .active_session
            .value
            .as_ref()?;
        Some((session.workspace_id.clone(), session.workspace_root.clone()))
    }

    /// Fetches the picture an image-generation card refers to.
    ///
    /// The runtime writes a reference, not the pixels: a workspace path for a
    /// picture the Agent saved, or a URL for one a provider is hosting. The
    /// path is read through the same file route an attachment preview uses;
    /// a URL is handed to the image element, which is the one thing on this
    /// client that can fetch for itself.
    fn ensure_generated_image(&mut self, reference: &str, cx: &mut Context<Self>) {
        let reference = reference.trim();
        if reference.is_empty() || self.generated_images.contains_key(reference) {
            return;
        }
        if reference.starts_with("http://") || reference.starts_with("https://") {
            // The element fetches this one; recording it is what keeps a
            // repaint from handing the same URL over again.
            self.generated_images.insert(
                reference.to_string(),
                GeneratedImageState::Remote(reference.to_string()),
            );
            return;
        }
        let Some((workspace_id, workspace_root)) = self.active_workspace_context() else {
            self.generated_images
                .insert(reference.to_string(), GeneratedImageState::Unavailable);
            return;
        };
        let Some(path) = message_attachment_workspace_path(reference, Some(&workspace_root)) else {
            self.generated_images
                .insert(reference.to_string(), GeneratedImageState::Unavailable);
            return;
        };
        let Some(format) = crate::workbench::image_format_for_path(&path) else {
            self.generated_images
                .insert(reference.to_string(), GeneratedImageState::Unavailable);
            return;
        };
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.generated_images
            .insert(reference.to_string(), GeneratedImageState::Loading);
        let key = reference.to_string();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend.download_file(workspace_id, path).await
        });
        let task = cx.spawn(async move |entity: WeakEntity<Self>, cx| {
            let outcome = flatten_join(runner.await);
            let _ = entity.update(cx, |this, cx| {
                let state = match outcome {
                    Ok(bytes) => {
                        GeneratedImageState::Ready(Arc::new(Image::from_bytes(format, bytes)))
                    }
                    Err(_) => GeneratedImageState::Unavailable,
                };
                this.generated_images.insert(key, state);
                cx.notify();
            });
        });
        self.tasks.push(task);
        cx.notify();
    }

    fn close_attachment_preview(
        &mut self,
        _: &MouseUpEvent,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.attachment_preview = None;
        self.attachment_preview_loading = None;
        cx.notify();
    }

    fn timeline_row_icon_path_for_row(&self, row: &TimelineRow) -> &'static str {
        self.timeline_row_latest_payload(row)
            .map(timeline_payload_icon_path)
            .unwrap_or_else(|| timeline_row_icon_path(row.kind))
    }

    fn render_timeline_process_rows(
        &self,
        turn: &TimelineConversationTurn,
        cx: &mut Context<Self>,
    ) -> Vec<gpui::AnyElement> {
        let mut elements = Vec::new();
        let mut row_index = 0;
        let mut group_index = 0;
        let settings = self.effective_timeline_display_settings();
        let groups = timeline_process_activity_groups_for_display(
            turn,
            settings.enhanced_command_execution_display,
            settings.enhanced_file_operation_display,
        );

        while row_index < turn.process_rows.len() {
            while groups
                .get(group_index)
                .is_some_and(|group| group.end_row <= row_index)
            {
                group_index += 1;
            }
            let group = groups.get(group_index).filter(|group| {
                group.start_row == row_index
                    && group.end_row <= turn.process_rows.len()
                    && group.end_row > group.start_row
            });
            if let Some(group) = group {
                elements.push(self.render_process_activity_group(
                    turn,
                    group,
                    &turn.process_rows[group.start_row..group.end_row],
                    cx,
                ));
                row_index = group.end_row;
                group_index += 1;
                continue;
            }
            elements.push(self.render_timeline_row(turn, &turn.process_rows[row_index], false, cx));
            row_index += 1;
        }

        elements
    }

    fn render_timeline_row(
        &self,
        turn: &TimelineConversationTurn,
        row: &TimelineRow,
        conversation_conclusion: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let settings = self.effective_timeline_display_settings();
        match row.kind {
            TimelineRowKind::UserMessage => {
                let latest = self.user_row_is_latest(row);
                self.render_user_message_row(row, latest, turn.complete, cx)
            }
            TimelineRowKind::AgentMessage => {
                self.render_agent_message_row(turn, row, conversation_conclusion, cx)
            }
            TimelineRowKind::Reasoning | TimelineRowKind::Plan => {
                self.render_thought_process_row(row, cx)
            }
            TimelineRowKind::Error => self.render_error_row(row, conversation_conclusion),
            TimelineRowKind::PermissionRequest => self.render_permission_request_card(row, cx),
            TimelineRowKind::ElicitationRequest => self.render_elicitation_request_card(row, cx),
            TimelineRowKind::Command if settings.enhanced_command_execution_display => {
                self.render_command_execution_card(row, cx)
            }
            TimelineRowKind::Command => self.render_process_activity_line(row, cx),
            TimelineRowKind::FileOperation if settings.enhanced_file_operation_display => {
                self.render_file_operation_card(row, cx)
            }
            TimelineRowKind::FileOperation => self.render_process_activity_line(row, cx),
            TimelineRowKind::ImageGeneration => self.render_image_generation_card(row, cx),
            TimelineRowKind::ToolCall
            | TimelineRowKind::WebSearch
            | TimelineRowKind::TodoUpdate
            | TimelineRowKind::Collaboration
            | TimelineRowKind::Retry => self.render_process_activity_line(row, cx),
            TimelineRowKind::GitNotice
            | TimelineRowKind::SystemNotice
            | TimelineRowKind::PermissionResolution
            | TimelineRowKind::ElicitationResolution => self.render_fallback_process_row(row),
        }
    }

    fn render_user_message_row(
        &self,
        row: &TimelineRow,
        is_latest_turn: bool,
        turn_complete: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let attachments = self.timeline_row_user_attachments(row);
        let row_id = row.id.clone();
        let attachment_elements = attachments.iter().enumerate().map(|(index, attachment)| {
            let attachment = attachment.clone();
            let is_image = message_attachment_is_image(&attachment);
            let label = if attachment.label.trim().is_empty() {
                locale::text("Image", "图片", "圖片").to_string()
            } else {
                attachment.label.clone()
            };
            let action_attachment = attachment.clone();
            div()
                .id(format!("user-attachment:{row_id}:{index}"))
                .w_full()
                .min_w_0()
                .mt_2()
                .px_2()
                .py_2()
                .rounded(px(theme::RADIUS_CONTROL))
                .border_1()
                .border_color(theme::border_subtle())
                .bg(theme::bg_card_dim())
                .flex()
                .items_center()
                .gap_2()
                .cursor_pointer()
                .active(|style| style.bg(theme::row_pressed_bg()))
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, _, window, cx| {
                        this.open_user_attachment(action_attachment.clone(), window, cx)
                    }),
                )
                .child(
                    svg()
                        .path(if is_image {
                            "icons/image.svg"
                        } else {
                            "icons/file-text.svg"
                        })
                        .size(px(16.0))
                        .flex_shrink_0()
                        .text_color(theme::text_secondary()),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .overflow_hidden()
                        .text_ellipsis()
                        .whitespace_nowrap()
                        .text_size(theme::font_caption())
                        .text_color(theme::text_secondary())
                        .child(label),
                )
                .child(
                    svg()
                        .path("icons/chevron-right.svg")
                        .size(px(14.0))
                        .flex_shrink_0()
                        .text_color(theme::text_muted()),
                )
        });
        let submitted_at = (row.timestamp_ms > 0).then_some(row.timestamp_ms);
        div()
            .id(row.id.clone())
            .w_full()
            .flex()
            .flex_col()
            .items_end()
            .child(
                div()
                    .w(gpui::relative(0.78))
                    .max_w(px(520.0))
                    .rounded(px(theme::RADIUS_CARD))
                    .border_1()
                    .border_color(theme::border_default())
                    .bg(theme::bg_card())
                    .px_3()
                    .py_2()
                    .text_size(theme::font_body())
                    .line_height(px(22.0))
                    .text_color(theme::text_primary())
                    .whitespace_normal()
                    .child(row.body.clone())
                    .children(attachment_elements),
            )
            // A permanent timestamp. The desktop reveals its actions on hover;
            // a phone has no hover, and the row's duration hint needed a press.
            .child({
                let copy_text = row.body.clone();
                let share_user_text = row.body.clone();
                let editing = self
                    .composer_message_edit
                    .as_ref()
                    .is_some_and(|edit| edit.row_id == row.id);
                let edit_enabled = !editing
                    && self.user_message_edit_available(is_latest_turn, turn_complete)
                    && !self.composer_history_open;
                let edit_row = row.clone();
                div()
                    .w(gpui::relative(0.78))
                    .max_w(px(520.0))
                    .mt(px(2.0))
                    .pr(px(2.0))
                    .flex()
                    .items_center()
                    .justify_end()
                    .gap_1()
                    .when_some(submitted_at, |line, submitted_at| {
                        line.child(
                            div()
                                .flex_1()
                                .min_w_0()
                                .text_size(theme::font_micro())
                                .text_color(theme::text_muted())
                                .child(session_sidebar_time_label(submitted_at)),
                        )
                    })
                    .child(
                        timeline_action_button(
                            format!("copy-user-message:{}", row.id),
                            "icons/copy.svg",
                            locale::text("Copy", "复制", "複製"),
                        )
                        .on_mouse_up(
                            MouseButton::Left,
                            cx.listener(move |_, _, _, cx| {
                                cx.write_to_clipboard(ClipboardItem::new_string(copy_text.clone()));
                            }),
                        ),
                    )
                    .child(
                        timeline_action_button(
                            format!("share-user-message:{}", row.id),
                            "icons/upload.svg",
                            locale::text("Share", "分享", "分享"),
                        )
                        .on_mouse_up(
                            MouseButton::Left,
                            cx.listener(move |this, _, _, cx| {
                                if let Err(error) = crate::share::share_text(&share_user_text) {
                                    this.fail(error);
                                }
                                cx.notify();
                            }),
                        ),
                    )
                    // Only the newest prompt can be rewritten, so the control
                    // is drawn there and dimmed when the session is mid-turn:
                    // hiding it entirely would leave the reader guessing why
                    // the desktop has an edit and the phone does not.
                    .when(is_latest_turn, |line| {
                        line.child(
                            timeline_action_button(
                                format!("edit-user-message:{}", row.id),
                                if editing {
                                    "icons/x.svg"
                                } else {
                                    "icons/pencil.svg"
                                },
                                if editing {
                                    locale::text("Cancel editing", "取消编辑", "取消編輯")
                                } else {
                                    locale::text("Edit", "编辑", "編輯")
                                },
                            )
                            .when(edit_enabled || editing, |button| {
                                button
                                    .cursor_pointer()
                                    .active(|style| style.bg(theme::row_pressed_bg()))
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(move |this, _, window, cx| {
                                            if this.composer_message_edit.is_some() {
                                                this.cancel_user_message_edit(window, cx);
                                            } else {
                                                this.begin_user_message_edit(&edit_row, window, cx);
                                            }
                                        }),
                                    )
                            })
                            .when(!edit_enabled && !editing, |button| button.opacity(0.4)),
                        )
                    })
            })
            .into_any_element()
    }

    fn render_markdown_view(
        &self,
        key: String,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> Entity<markdown::MarkdownView> {
        let revision = row.last_sequence.max(0) as u64;
        let mut views = self.timeline_markdown_views.borrow_mut();
        if let Some((view, cached_revision, cached_source)) = views.get_mut(&key) {
            let source =
                if *cached_revision == revision && cached_source.as_ref() == row.body.as_str() {
                    cached_source.clone()
                } else {
                    Arc::<str>::from(row.body.as_str())
                };
            *cached_revision = revision;
            *cached_source = source.clone();
            let view = view.clone();
            drop(views);
            view.update(cx, |view, cx| {
                view.set_source(source, revision, cx);
                view.set_muted(row.kind == TimelineRowKind::Reasoning, cx);
            });
            return view;
        }

        let source = Arc::<str>::from(row.body.as_str());
        let view = cx.new(|cx| {
            markdown::render(
                source.clone(),
                revision,
                row.kind == TimelineRowKind::Reasoning,
                cx,
            )
        });
        if views.len() >= TIMELINE_MARKDOWN_VIEW_CACHE_LIMIT
            && let Some(evicted) = views.keys().next().cloned()
        {
            views.remove(&evicted);
        }
        views.insert(key, (view.clone(), revision, source));
        view
    }

    fn render_agent_message_row(
        &self,
        turn: &TimelineConversationTurn,
        row: &TimelineRow,
        conversation_conclusion: bool,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        div()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .flex()
            .flex_col()
            .gap_2()
            .child(self.render_markdown_view(format!("markdown:{}", row.id), row, cx))
            .when_some(
                conversation_conclusion
                    .then(|| self.render_agent_answer_metadata(turn, row, cx))
                    .flatten(),
                |message, metadata| message.child(metadata),
            )
            .into_any_element()
    }

    fn render_agent_answer_metadata(
        &self,
        turn: &TimelineConversationTurn,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> Option<gpui::AnyElement> {
        if !turn.complete || row.kind != TimelineRowKind::AgentMessage || row.body.trim().is_empty()
        {
            return None;
        }
        let attribution = turn
            .runtime_attribution
            .as_deref()
            .map(runtime_attribution_line);
        let (agent_identity, runtime_label) =
            timeline_runtime_attribution_parts(attribution.as_deref());
        let duration = format_compact_duration(
            turn.started_at_ms,
            (turn.complete || turn.superseded)
                .then_some(turn.ended_at_ms)
                .flatten(),
        );
        let generation_time = format_generation_time(turn.started_at_ms, turn.ended_at_ms);
        let runtime_value = runtime_label.unwrap_or_default();
        let runtime_display =
            truncate_single_line(&runtime_value, TIMELINE_RUNTIME_LABEL_MAX_CHARS);
        let turn_id = turn.id.clone();
        let row_id = row.id.clone();
        let copy_text = row.body.clone();
        let share_text = row.body.clone();
        let fork_sequence = row.last_sequence;
        let fork_available = fork_sequence > 0
            && !self.fork_session_busy
            && self.backend.as_ref().is_some_and(|backend| {
                backend
                    .capability_snapshot()
                    .agent
                    .supports(BackendOperation::AgentForkSession)
            });
        let runtime_tip = TimelineMetadataTip::Runtime {
            row_id: row.id.clone(),
            value: runtime_value.clone(),
        };
        let duration_tip = TimelineMetadataTip::Duration {
            row_id: row.id.clone(),
            value: generation_time.clone(),
        };
        let active_tip = self
            .timeline_metadata_tip
            .as_ref()
            .filter(|tip| match tip {
                TimelineMetadataTip::Runtime { row_id: id, .. }
                | TimelineMetadataTip::Duration { row_id: id, .. } => id == &row.id,
            })
            .cloned();
        let tip_text = active_tip.as_ref().map(|tip| match tip {
            TimelineMetadataTip::Runtime { value, .. } => value.clone(),
            TimelineMetadataTip::Duration { value, .. } => value.clone(),
        });
        Some(
            div()
                .id(format!("agent-answer-metadata:{}", row.id))
                .w_full()
                .min_w_0()
                .mt_1()
                .flex()
                .flex_col()
                .gap_1()
                .text_size(theme::font_micro())
                .text_color(theme::text_muted())
                .child(
                    div()
                        .w_full()
                        .min_w_0()
                        .flex()
                        .items_center()
                        .justify_between()
                        .gap_2()
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .flex()
                                .items_center()
                                .gap_2()
                                .child(
                                    svg()
                                        .path(agent_icon_path(
                                            agent_identity.as_deref().unwrap_or("unknown"),
                                        ))
                                        .size(px(theme::ICON_SM))
                                        .flex_shrink_0()
                                        .text_color(theme::text_muted()),
                                )
                                .when(!runtime_value.is_empty(), |left| {
                                    let runtime_tip = runtime_tip.clone();
                                    left.child(
                                        div()
                                            .id(format!("runtime-label:{row_id}"))
                                            .min_w_0()
                                            .flex_1()
                                            .overflow_hidden()
                                            .text_ellipsis()
                                            .whitespace_nowrap()
                                            .cursor_pointer()
                                            .on_mouse_up(
                                                MouseButton::Left,
                                                cx.listener(move |this, _, _, cx| {
                                                    this.toggle_timeline_metadata_tip(
                                                        runtime_tip.clone(),
                                                        cx,
                                                    )
                                                }),
                                            )
                                            .child(runtime_display.clone()),
                                    )
                                })
                                .child(
                                    div()
                                        .id(format!("duration-label:{row_id}"))
                                        .flex_shrink_0()
                                        .flex()
                                        .items_center()
                                        .gap_1()
                                        .cursor_pointer()
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(move |this, _, _, cx| {
                                                this.toggle_timeline_metadata_tip(
                                                    duration_tip.clone(),
                                                    cx,
                                                )
                                            }),
                                        )
                                        .child(
                                            svg()
                                                .path("icons/clock.svg")
                                                .size(px(theme::ICON_SM))
                                                .flex_shrink_0()
                                                .text_color(theme::text_muted()),
                                        )
                                        .child(duration),
                                ),
                        )
                        .child(
                            div()
                                .flex_shrink_0()
                                .flex()
                                .items_center()
                                .justify_end()
                                .gap_1()
                                .child(
                                    timeline_action_button(
                                        format!("copy-answer:{}", row.id),
                                        "icons/copy.svg",
                                        locale::text("Copy", "复制", "複製"),
                                    )
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(move |_, _, _, cx| {
                                            cx.write_to_clipboard(ClipboardItem::new_string(
                                                copy_text.clone(),
                                            ));
                                        }),
                                    ),
                                )
                                .child(
                                    timeline_action_button(
                                        format!("share-answer:{}", row.id),
                                        "icons/upload.svg",
                                        locale::text("Share", "分享", "分享"),
                                    )
                                    .on_mouse_up(
                                        MouseButton::Left,
                                        cx.listener(move |this, _, _, cx| {
                                            if let Err(error) =
                                                crate::share::share_text(&share_text)
                                            {
                                                this.fail(error);
                                            }
                                            cx.notify();
                                        }),
                                    ),
                                )
                                .when(turn.user_row.is_some(), |actions| {
                                    actions.child(
                                        timeline_action_button(
                                            format!("scroll-to-user:{}", row.id),
                                            "icons/arrow-to-top.svg",
                                            locale::text(
                                                "Scroll to User Message",
                                                "滚动到用户消息",
                                                "捲動到使用者訊息",
                                            ),
                                        )
                                        .on_mouse_up(
                                            MouseButton::Left,
                                            cx.listener(move |this, _, _, cx| {
                                                this.scroll_to_timeline_turn(&turn_id, cx);
                                            }),
                                        ),
                                    )
                                })
                                .child(
                                    timeline_action_button(
                                        format!("fork-answer:{}", row.id),
                                        "icons/git-branch.svg",
                                        locale::text("Fork", "分叉会话", "分支會話"),
                                    )
                                    .when(fork_available, |button| {
                                        button
                                            .cursor_pointer()
                                            .active(|style| style.bg(theme::row_pressed_bg()))
                                            .on_mouse_up(
                                                MouseButton::Left,
                                                cx.listener(move |this, _, _, cx| {
                                                    this.fork_session_at(fork_sequence, cx);
                                                }),
                                            )
                                    })
                                    .when(!fork_available, |button| button.opacity(0.4)),
                                ),
                        ),
                )
                .when_some(tip_text, |metadata, text| {
                    metadata.child(
                        div()
                            .id(format!("metadata-tip:{row_id}"))
                            .w_full()
                            .px_2()
                            .py_1()
                            .rounded(px(theme::RADIUS_CONTROL))
                            .bg(theme::bg_card_dim())
                            .text_color(theme::text_secondary())
                            .whitespace_normal()
                            .cursor_pointer()
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(|this, _, _, cx| {
                                    this.timeline_metadata_tip = None;
                                    cx.notify();
                                }),
                            )
                            .child(text),
                    )
                })
                .into_any_element(),
        )
    }

    fn scroll_to_timeline_turn(&mut self, turn_id: &str, _cx: &mut Context<Self>) {
        if let Some(index) = self
            .timeline_turns
            .iter()
            .position(|turn| turn.id == turn_id)
        {
            self.timeline_list.scroll_to(ListOffset {
                item_ix: index,
                offset_in_item: px(0.0),
            });
        }
    }

    fn fork_session_at(&mut self, through_sequence: i64, cx: &mut Context<Self>) {
        if self.fork_session_busy || through_sequence <= 0 {
            return;
        }
        let Some(backend) = self.backend.clone().filter(|backend| {
            backend
                .capability_snapshot()
                .agent
                .supports(BackendOperation::AgentForkSession)
        }) else {
            self.fail(BackendError::unsupported(
                "agent_session_fork_unavailable",
                locale::text(
                    "Session forking is unavailable on this desktop.",
                    "此桌面端不支持分叉会话。",
                    "此桌面版不支援分支工作階段。",
                ),
            ));
            cx.notify();
            return;
        };
        let Some(source_session_id) = self
            .controller
            .as_ref()
            .and_then(|controller| controller.state.selected_session_id.clone())
        else {
            return;
        };
        self.fork_session_busy = true;
        let request = MutationRequest::new(ForkAgentSessionRequest {
            source_session_id,
            through_sequence,
            expected_source_end_sequence: None,
        });
        let runner =
            gpui_tokio::Tokio::spawn(cx, async move { backend.fork_session(request).await });
        let task = cx.spawn(async move |entity: WeakEntity<Self>, cx| {
            let outcome = flatten_join(runner.await);
            let _ = entity.update(cx, |this, cx| {
                this.fork_session_busy = false;
                match outcome {
                    Ok(session) => {
                        let session_id = session.id.clone();
                        this.hint(
                            Tone::Success,
                            locale::text(
                                "Forked session created",
                                "分叉会话已创建",
                                "分支工作階段已建立",
                            ),
                        );
                        this.refresh_sessions(cx);
                        this.open_session(session_id, cx);
                    }
                    Err(error) => this.fail(error),
                }
                cx.notify();
            });
        });
        self.tasks.push(task);
        cx.notify();
    }

    fn render_thought_process_row(
        &self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        if row.kind == TimelineRowKind::Reasoning {
            return self.render_reasoning_row(row, cx);
        }
        // Plans retain the compact muted markdown presentation used by the
        // existing process timeline.
        if row.body.trim().is_empty() {
            return div().id(row.id.clone()).into_any_element();
        }
        div()
            .id(format!("thought:{}", row.id))
            .w_full()
            .min_w_0()
            .text_color(theme::text_secondary())
            .child(self.render_markdown_view(format!("thought:{}", row.id), row, cx))
            .into_any_element()
    }

    fn render_image_generation_card(
        &self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let Some(TimelinePayload::ImageGeneration(image)) = self.timeline_row_latest_payload(row)
        else {
            return self.render_process_activity_line(row, cx);
        };
        let has_details = !image.summary.trim().is_empty() || image.image_reference.is_some();
        let can_expand = has_details && !row.streaming;
        let expanded = has_details && (row.streaming || self.timeline_row_expanded(&row.id));
        let row_id = row.id.clone();
        let failed = image.status == vibex_core::ToolCallStatus::Failed;
        let title = if image.summary.trim().is_empty() {
            locale::text("Image generation", "图片生成", "圖片生成").to_string()
        } else {
            image.summary.clone()
        };
        div()
            .id(format!("image-generation-card:{}", row.id))
            .w_full()
            .min_w_0()
            .overflow_hidden()
            .rounded(px(theme::RADIUS_CARD))
            .border_1()
            .border_color(if failed {
                theme::accent_red().opacity(0.46)
            } else {
                theme::border_default()
            })
            .bg(theme::bg_card_dim())
            .child(
                div()
                    .id(format!("image-generation-card-header:{}", row.id))
                    .w_full()
                    .min_w_0()
                    .min_h(px(40.0))
                    .px_3()
                    .flex()
                    .items_center()
                    .gap_2()
                    .when(can_expand, |header| {
                        let reference = image.image_reference.clone();
                        header
                            .cursor_pointer()
                            .active(|style| style.bg(theme::row_pressed_bg()))
                            .on_mouse_up(
                                MouseButton::Left,
                                cx.listener(move |this, _, _, cx| {
                                    // Opening the card is what asks for the
                                    // picture: a closed card costs nothing.
                                    if !this.timeline_row_expanded(&row_id)
                                        && let Some(reference) = reference.as_deref()
                                    {
                                        this.ensure_generated_image(reference, cx);
                                    }
                                    this.toggle_timeline_row(row_id.clone(), cx)
                                }),
                            )
                    })
                    .child(
                        svg()
                            .path("icons/image.svg")
                            .size(px(14.0))
                            .flex_shrink_0()
                            .text_color(if failed {
                                theme::accent_red()
                            } else {
                                theme::text_muted()
                            }),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .text_size(theme::font_caption())
                            .text_color(theme::text_primary())
                            .child(title),
                    )
                    .when(can_expand, |header| {
                        header.child(
                            svg()
                                .path(if expanded {
                                    "icons/chevron-down.svg"
                                } else {
                                    "icons/chevron-right.svg"
                                })
                                .size(px(theme::ICON_SM))
                                .flex_shrink_0()
                                .text_color(theme::text_muted()),
                        )
                    })
                    .child(timeline_status_badge(
                        timeline_row_status_label(row),
                        timeline_row_color(row),
                    )),
            )
            .when(expanded, |card| {
                card.child(
                    div()
                        .border_t_1()
                        .border_color(theme::border_subtle())
                        .p_3()
                        .flex()
                        .flex_col()
                        .gap_2()
                        .when(!image.summary.trim().is_empty(), |details| {
                            details.child(self.render_timeline_detail(
                                locale::text("Summary", "摘要", "摘要"),
                                &image.summary,
                            ))
                        })
                        .when_some(image.image_reference.as_ref(), |details, reference| {
                            details.child(self.render_generated_image(reference)).child(
                                self.render_timeline_detail(
                                    locale::text("Image reference", "图片引用", "圖片參照"),
                                    reference,
                                ),
                            )
                        }),
                )
            })
            .into_any_element()
    }

    /// The picture an image-generation card produced, when it can be shown.
    fn render_generated_image(&self, reference: &str) -> gpui::AnyElement {
        match self.generated_images.get(reference.trim()) {
            Some(GeneratedImageState::Ready(image)) => div()
                .w_full()
                .h(px(240.0))
                .rounded(px(theme::RADIUS_CONTROL))
                .border_1()
                .border_color(theme::border_subtle())
                .bg(theme::bg_card())
                .overflow_hidden()
                .flex()
                .items_center()
                .justify_center()
                .child(
                    img(image.clone())
                        .max_w_full()
                        .max_h_full()
                        .object_fit(ObjectFit::Contain),
                )
                .into_any_element(),
            Some(GeneratedImageState::Remote(url)) => div()
                .w_full()
                .h(px(240.0))
                .rounded(px(theme::RADIUS_CONTROL))
                .border_1()
                .border_color(theme::border_subtle())
                .bg(theme::bg_card())
                .overflow_hidden()
                .flex()
                .items_center()
                .justify_center()
                .child(
                    img(url.clone())
                        .max_w_full()
                        .max_h_full()
                        .object_fit(ObjectFit::Contain),
                )
                .into_any_element(),
            Some(GeneratedImageState::Loading) => div()
                .w_full()
                .h(px(64.0))
                .flex()
                .items_center()
                .justify_center()
                .text_size(theme::font_caption())
                .text_color(theme::text_muted())
                .child(locale::common("Loading"))
                .into_any_element(),
            // Nothing is drawn for a reference this client cannot show: the
            // reference line underneath is what says what it was.
            Some(GeneratedImageState::Unavailable) | None => div().into_any_element(),
        }
    }

    fn render_permission_request_card(
        &self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let Some(TimelinePayload::PermissionRequest(request)) =
            self.timeline_row_latest_payload(row)
        else {
            return self.render_fallback_process_row(row);
        };
        if request.status != vibex_core::PermissionRequestStatus::Pending {
            return self.render_fallback_process_row(row);
        }
        let approval = self
            .controller
            .as_ref()
            .and_then(|controller| {
                controller
                    .state
                    .approval_surfaces(ShellKind::Compact)
                    .into_iter()
                    .find(|approval| approval.request_id == request.id)
            })
            .unwrap_or_else(|| {
                vibex_ui::ApprovalSurfaceModel::from_request(request, ShellKind::Compact)
            });
        self.render_approval(&approval, cx).into_any_element()
    }

    fn render_elicitation_request_card(
        &self,
        row: &TimelineRow,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let Some(TimelinePayload::ElicitationRequest(request)) =
            self.timeline_row_latest_payload(row)
        else {
            return self.render_fallback_process_row(row);
        };
        if request.status != vibex_core::ElicitationRequestStatus::Pending {
            return self.render_fallback_process_row(row);
        }
        let surface = ElicitationSurfaceModel::from_request(request, ShellKind::Compact);
        self.render_elicitation(&surface, cx).into_any_element()
    }

    fn render_error_row(
        &self,
        row: &TimelineRow,
        conversation_conclusion: bool,
    ) -> gpui::AnyElement {
        let recoverable = self.timeline_row_latest_payload(row).is_some_and(
            |payload| matches!(payload, TimelinePayload::Error(error) if error.recoverable),
        );
        let color = if recoverable {
            theme::accent_yellow()
        } else {
            theme::accent_red()
        };
        let message = if row.body.trim().is_empty() {
            row.title.clone()
        } else {
            row.body.clone()
        };
        if conversation_conclusion {
            return div()
                .id(row.id.clone())
                .w_full()
                .min_w_0()
                .flex()
                .items_start()
                .gap_2()
                .text_size(theme::font_body())
                .line_height(px(18.0))
                .text_color(color)
                .child(
                    svg()
                        .path("icons/triangle-alert.svg")
                        .size(px(theme::ICON_SM))
                        .flex_shrink_0()
                        .text_color(color),
                )
                .child(div().min_w_0().flex_1().whitespace_normal().child(message))
                .into_any_element();
        }
        div()
            .id(row.id.clone())
            .w_full()
            .min_w_0()
            .rounded(px(theme::RADIUS_CARD))
            .border_1()
            .border_color(color.opacity(0.42))
            .bg(color.opacity(0.12))
            .px_3()
            .py_2()
            .flex()
            .items_start()
            .gap_2()
            .text_size(theme::font_caption())
            .line_height(px(17.0))
            .text_color(color)
            .child(
                svg()
                    .path("icons/triangle-alert.svg")
                    .size(px(theme::ICON_SM))
                    .flex_shrink_0()
                    .text_color(color),
            )
            .child(div().min_w_0().flex_1().whitespace_normal().child(message))
            .into_any_element()
    }

