/// Model ids emitted by the built-in Agent integrations keep their marks.
const MOBILE_MODEL_COMPATIBILITY_BRANDS: &[(&str, ModelBrandAsset)] = &[
    ("opencode", model_colored("icons/opencode.svg")),
    ("codex", model_themed("icons/openai.svg")),
    ("chatgpt", model_themed("icons/openai.svg")),
    ("copilot", model_themed("icons/copilot.svg")),
    ("tongyi", model_colored("icons/qwen.svg")),
    ("dashscope", model_colored("icons/qwen.svg")),
];

fn model_keyword_matches(model: &str, keyword: &str) -> bool {
    model.starts_with(keyword)
        && model.as_bytes().get(keyword.len()).is_none_or(|character| {
            matches!(
                character,
                b'-' | b'_' | b'.' | b'/' | b':' | b' ' | b'\t' | b'\n' | b'\r'
            )
        })
}

fn model_brand_prefix(model: &str) -> Option<ModelBrandAsset> {
    MOBILE_MODEL_BRAND_PREFIXES
        .iter()
        .filter(|(prefix, _)| model_keyword_matches(model, prefix))
        .max_by_key(|(prefix, _)| prefix.len())
        .map(|(_, asset)| *asset)
}

/// Desktop-parity model brand lookup: prefix exceptions, provider slugs,
/// longest keyword rules, built-in Agent compatibility aliases, then the
/// legacy gpt/o* and opus/sonnet/haiku fallbacks.
fn model_brand_asset(model_id: &str) -> Option<ModelBrandAsset> {
    let normalized = model_id.trim().to_ascii_lowercase();
    let normalized = normalized.strip_prefix('~').unwrap_or(&normalized);
    if normalized.is_empty() {
        return None;
    }

    if let Some(asset) = model_brand_prefix(normalized) {
        return Some(asset);
    }

    let (provider, model_name) = normalized
        .split_once('/')
        .map_or((normalized, normalized), |(provider, model_name)| {
            (provider, model_name)
        });
    if let Some((_, asset)) = MOBILE_MODEL_PROVIDER_BRANDS
        .iter()
        .find(|(candidate, _)| *candidate == provider)
    {
        return Some(*asset);
    }

    if let Some(asset) = model_brand_prefix(model_name) {
        return Some(asset);
    }

    if let Some((_, asset)) = MOBILE_MODEL_BRAND_RULES
        .iter()
        .filter(|(keyword, _)| model_keyword_matches(model_name, keyword))
        .max_by_key(|(keyword, _)| keyword.len())
    {
        return Some(*asset);
    }

    if let Some((_, asset)) = MOBILE_MODEL_COMPATIBILITY_BRANDS
        .iter()
        .find(|(keyword, _)| model_keyword_matches(model_name, keyword))
    {
        return Some(*asset);
    }

    if ["gpt", "o1", "o3", "o4", "o5"]
        .iter()
        .any(|keyword| model_keyword_matches(model_name, keyword))
    {
        agent_brand_identity_asset("openai")
    } else if ["opus", "sonnet", "haiku"]
        .iter()
        .any(|keyword| model_keyword_matches(model_name, keyword))
    {
        agent_brand_identity_asset("claude")
    } else {
        None
    }
}

fn agent_brand_asset(agent_id: &str, label: &str) -> Option<(&'static str, bool)> {
    agent_brand_identity_asset(&format!("{agent_id} {label}"))
}

fn agent_brand_identity_asset(identity: &str) -> Option<(&'static str, bool)> {
    let identity = identity.to_ascii_lowercase();
    MOBILE_AGENT_BRAND_ASSETS
        .iter()
        .find(|(needle, _, _)| identity.contains(needle))
        .map(|(_, path, uses_current_color)| (*path, *uses_current_color))
}

/// Brand icon for an Agent, desktop-style: colored marks render through
/// `img` to keep their embedded palette; themed marks and the bot fallback
/// are tinted with `tint`.
fn runtime_agent_icon(
    agent_id: &AgentId,
    label: &str,
    size: gpui::Pixels,
    tint: Hsla,
) -> gpui::AnyElement {
    match agent_brand_asset(agent_id.as_str(), label) {
        Some((path, false)) => img(path).size(size).flex_shrink_0().into_any_element(),
        Some((path, true)) => svg()
            .path(path)
            .size(size)
            .flex_shrink_0()
            .text_color(tint)
            .into_any_element(),
        None => svg()
            .path("icons/bot.svg")
            .size(size)
            .flex_shrink_0()
            .text_color(tint)
            .into_any_element(),
    }
}

/// Brand icon for a model id, desktop-style: colored marks render through
/// `img`; themed marks are tinted with `tint` and unknown ids fall back to
/// the sparkles glyph.
fn runtime_model_icon(model_id: Option<&str>, size: gpui::Pixels, tint: Hsla) -> gpui::AnyElement {
    match model_id.and_then(model_brand_asset) {
        Some((path, false)) => img(path).size(size).flex_shrink_0().into_any_element(),
        Some((path, true)) => svg()
            .path(path)
            .size(size)
            .flex_shrink_0()
            .text_color(tint)
            .into_any_element(),
        None => svg()
            .path("icons/sparkles.svg")
            .size(size)
            .flex_shrink_0()
            .text_color(theme::accent_green())
            .into_any_element(),
    }
}

fn runtime_model_selection_key(model: &RuntimeModelSelection) -> String {
    match model {
        RuntimeModelSelection::Explicit { model_id } => format!("model:{model_id}"),
        RuntimeModelSelection::AgentDefault => "agent-default".to_string(),
    }
}

fn runtime_auth_source_display_label(source: &RuntimeAuthSourceSummary) -> String {
    match source.kind {
        RuntimeAuthSourceKind::AgentAccount => {
            locale::text("Agent account", "Agent 账户", "Agent 帳戶").to_string()
        }
        RuntimeAuthSourceKind::ProviderProfile => source.label.clone(),
    }
}

/// The account a selection runs as, named in the reader's language.
///
/// The runtime labels its own account in English because it serves every
/// client at once, but an Agent account is the product's own concept rather
/// than a name the reader chose, so this client names it from the kind; a
/// Provider Profile keeps the name its owner gave it.
fn runtime_auth_source_selection_label(
    auth_source: &vibex_core::RuntimeAuthSource,
    fallback: &str,
) -> String {
    match auth_source {
        vibex_core::RuntimeAuthSource::AgentAccount { .. } => {
            locale::text("Agent account", "Agent 账户", "Agent 帳戶").to_string()
        }
        vibex_core::RuntimeAuthSource::ProviderProfile { .. } => fallback.to_string(),
    }
}

fn runtime_auth_source_status_label(
    availability: RuntimeAuthSourceAvailability,
    model_count: usize,
) -> String {
    match availability {
        RuntimeAuthSourceAvailability::Available => runtime_model_count_label(model_count),
        RuntimeAuthSourceAvailability::RequiresAuthentication => {
            locale::text("Sign in", "需要登录", "需要登入").to_string()
        }
        RuntimeAuthSourceAvailability::Verifying => {
            locale::text("Verifying", "正在验证", "正在驗證").to_string()
        }
        RuntimeAuthSourceAvailability::DiscoveringModels => {
            locale::text("Loading models", "正在读取模型", "正在讀取模型").to_string()
        }
        RuntimeAuthSourceAvailability::TemporarilyUnavailable => {
            locale::text("Unavailable", "暂不可用", "暫不可用").to_string()
        }
        RuntimeAuthSourceAvailability::RequiresConfiguration => {
            locale::text("Configure", "需要配置", "需要設定").to_string()
        }
        RuntimeAuthSourceAvailability::Unsupported => {
            locale::text("Unsupported", "暂不支持", "暫不支援").to_string()
        }
    }
}

fn runtime_model_count_label(count: usize) -> String {
    match locale::current() {
        vibex_ui::locale::Locale::En => format!("{count} models"),
        vibex_ui::locale::Locale::ZhCn => format!("{count} 个模型"),
        vibex_ui::locale::Locale::ZhTw => format!("{count} 個模型"),
    }
}

fn runtime_choice_button(
    id: impl Into<ElementId>,
    label: impl Into<String>,
    selected: bool,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .min_w_0()
        .max_w_full()
        .h(px(theme::TOUCH_TARGET))
        .px_3()
        .rounded(px(theme::RADIUS_CONTROL))
        .border_1()
        .border_color(if selected {
            theme::accent_blue()
        } else {
            theme::border_default()
        })
        .bg(if selected {
            theme::bg_card()
        } else {
            theme::bg_card_dim()
        })
        .flex()
        .items_center()
        .justify_center()
        .text_size(theme::font_caption())
        .text_color(if selected {
            theme::text_primary()
        } else {
            theme::text_secondary()
        })
        .child(
            div()
                .max_w_full()
                .overflow_hidden()
                .text_ellipsis()
                .whitespace_nowrap()
                .child(label.into()),
        )
}

fn runtime_sheet_action_button(
    id: impl Into<ElementId>,
    label: impl Into<String>,
    primary: bool,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .h(px(theme::TOUCH_TARGET))
        .px_4()
        .rounded(px(theme::RADIUS_CONTROL))
        .border_1()
        .border_color(if primary {
            theme::text_primary()
        } else {
            theme::border_default()
        })
        .bg(if primary {
            theme::text_primary()
        } else {
            theme::bg_card()
        })
        .flex()
        .items_center()
        .justify_center()
        .text_size(theme::font_body())
        .text_color(if primary {
            theme::bg_primary()
        } else {
            theme::text_secondary()
        })
        .child(label.into())
}

/// A status dot plus the words for the same state. Every runtime surface pairs
/// the two, so a state never depends on color alone.
fn runtime_status_line(status: &RuntimeStatusView, text_color: gpui::Hsla) -> gpui::AnyElement {
    div()
        .flex()
        .items_center()
        .gap(px(theme::SPACING_SM))
        .child(
            div()
                .size(px(theme::ICON_STATUS))
                .flex_shrink_0()
                .rounded_full()
                .bg(status.status.dot_color()),
        )
        .child(
            div()
                .min_w_0()
                .overflow_hidden()
                .text_ellipsis()
                .whitespace_nowrap()
                .text_size(theme::font_caption())
                .text_color(text_color)
                .child(status.label()),
        )
        .into_any_element()
}

/// One full-width row of the runtime action sheet. The danger variant carries
/// the destructive color used by the app's other remove actions, and the row
/// uses the same metrics as the sidebar's per-row menu.
fn host_sheet_action_row(
    id: impl Into<ElementId>,
    label: impl Into<String>,
    danger: bool,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .h(px(theme::TOUCH_TARGET))
        .px_3()
        .rounded(px(theme::RADIUS_CONTROL))
        .flex()
        .items_center()
        .cursor_pointer()
        .active(|style| style.bg(theme::row_pressed_bg()))
        .text_size(theme::font_body())
        .text_color(if danger {
            theme::accent_red()
        } else {
            theme::text_primary()
        })
        .child(label.into())
}

/// The localized runtime-kind label for the detail page. `Unknown` keeps the
/// generic "Runtime" copy: a peer that never reported a kind is shown without
/// one rather than guessed at.
fn host_kind_label_for(locale: Locale, kind: RemoteServerKind) -> &'static str {
    match kind {
        RemoteServerKind::Desktop => locale::text_for(locale, "Desktop", "桌面端", "桌面版"),
        RemoteServerKind::Headless => {
            locale::text_for(locale, "Headless server", "无头服务器", "無頭伺服器")
        }
        RemoteServerKind::Unknown => locale::common_for(locale, "Runtime"),
    }
}

fn host_kind_label(kind: RemoteServerKind) -> &'static str {
    host_kind_label_for(locale::current(), kind)
}

/// The glyph a runtime's kind wears on its row. A computer on a desk and a
/// machine that only exists as a server are the two shapes the phone can reach,
/// and a peer that never said which it is keeps the generic server glyph.
fn host_kind_icon(kind: RemoteServerKind) -> &'static str {
    match kind {
        RemoteServerKind::Desktop => "icons/monitor.svg",
        RemoteServerKind::Headless | RemoteServerKind::Unknown => "icons/server.svg",
    }
}

/// One read-only field of the runtime detail page: a label column and the
/// stored value beside it.
fn host_detail_field(
    label: &'static str,
    value: &str,
    muted: bool,
    monospace: bool,
) -> gpui::AnyElement {
    let mut value_element = div()
        .min_w_0()
        .text_size(if muted {
            theme::font_caption()
        } else {
            theme::font_body()
        })
        .text_color(if muted {
            theme::text_muted()
        } else {
            theme::text_primary()
        })
        .child(value.to_string());
    if monospace {
        value_element = value_element
            .font_family("monospace")
            .overflow_hidden()
            .text_ellipsis()
            .whitespace_nowrap();
    }
    div()
        .w_full()
        .flex()
        .items_start()
        .gap(px(theme::SPACING_MD))
        .py(px(theme::SPACING_SM))
        .child(
            div()
                .w(px(96.0))
                .flex_shrink_0()
                .text_size(theme::font_caption())
                .text_color(theme::text_muted())
                .child(locale::common(label)),
        )
        .child(div().flex_1().min_w_0().child(value_element))
        .into_any_element()
}

/// The "last connected" line for a runtime the phone is not on right now.
/// Coarse buckets are deliberate: a row shows one compact line, and the exact
/// minute is not actionable.
fn host_last_connected_label(timestamp_ms: i64) -> String {
    let resolved = locale::current();
    let Some(local) = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(timestamp_ms)
        .map(|timestamp| timestamp.with_timezone(&chrono::Local))
    else {
        return String::new();
    };
    let seconds = chrono::Local::now()
        .signed_duration_since(local)
        .num_seconds()
        .max(0);
    if seconds < 60 {
        return locale::text(
            "Last connected just now",
            "上次连接：刚刚",
            "上次連線：剛剛",
        )
        .to_string();
    }
    if seconds < 3_600 {
        let minutes = seconds / 60;
        return match resolved {
            vibex_ui::locale::Locale::En => format!("Last connected {minutes}m ago"),
            vibex_ui::locale::Locale::ZhCn => format!("上次连接：{minutes} 分钟前"),
            vibex_ui::locale::Locale::ZhTw => format!("上次連線：{minutes} 分鐘前"),
        };
    }
    if seconds < 86_400 {
        let hours = seconds / 3_600;
        return match resolved {
            vibex_ui::locale::Locale::En => format!("Last connected {hours}h ago"),
            vibex_ui::locale::Locale::ZhCn => format!("上次连接：{hours} 小时前"),
            vibex_ui::locale::Locale::ZhTw => format!("上次連線：{hours} 小時前"),
        };
    }
    let days = seconds / 86_400;
    match resolved {
        vibex_ui::locale::Locale::En => format!("Last connected {days}d ago"),
        vibex_ui::locale::Locale::ZhCn => format!("上次连接：{days} 天前"),
        vibex_ui::locale::Locale::ZhTw => format!("上次連線：{days} 天前"),
    }
}

