fn bounded_timeline_detail(value: &str) -> String {
    const MAX_CHARS: usize = 2_400;

    if value.chars().count() <= MAX_CHARS {
        return value.to_string();
    }
    let mut bounded = value
        .chars()
        .take(MAX_CHARS.saturating_sub(3))
        .collect::<String>();
    bounded.push_str("...");
    bounded
}

