    #[test]
    fn drawer_terminal_phases_do_not_depend_on_pixel_delta() {
        let mut event = ScrollWheelEvent {
            position: point(px(0.0), px(0.0)),
            delta: ScrollDelta::Lines(point(0.0, 0.0)),
            modifiers: gpui::Modifiers::default(),
            touch_phase: TouchPhase::Ended,
        };
        assert!(matches!(drawer_pan_input(&event), DrawerPanInput::Ended));

        event.touch_phase = TouchPhase::Cancelled;
        assert!(matches!(
            drawer_pan_input(&event),
            DrawerPanInput::Cancelled
        ));
    }

    #[test]
    fn main_page_swipes_open_the_page_in_the_finger_direction() {
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Main, 24.0, 4.0),
            DrawerPanDecision::Drag(DrawerPage::Sessions)
        );
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Main, -24.0, 4.0),
            DrawerPanDecision::Drag(DrawerPage::Workbench)
        );
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Page(DrawerPage::Sessions), -24.0, 4.0,),
            DrawerPanDecision::Drag(DrawerPage::Sessions)
        );
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Page(DrawerPage::Workbench), 24.0, 4.0,),
            DrawerPanDecision::Drag(DrawerPage::Workbench)
        );
    }

    #[test]
    fn drawer_pan_yields_to_vertical_scrolling_and_wrong_direction_swipes() {
        // A pan whose vertical travel clearly outgrows its horizontal travel
        // belongs to list scrolling.
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Main, 24.0, 40.0),
            DrawerPanDecision::Cancel
        );
        // Moderate diagonal drift is tolerated as a drawer swipe.
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Main, 24.0, 36.0),
            DrawerPanDecision::Drag(DrawerPage::Sessions)
        );
        // Sub-threshold horizontal travel with vertical drift is a scroll, too.
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Main, 8.0, 40.0),
            DrawerPanDecision::Cancel
        );
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Page(DrawerPage::Sessions), 24.0, 2.0,),
            DrawerPanDecision::Cancel
        );
        assert_eq!(
            drawer_pan_decision(DrawerDragOrigin::Page(DrawerPage::Workbench), -24.0, 2.0,),
            DrawerPanDecision::Cancel
        );
    }

    /// The back swipe over a page opened on top of another one: a deliberate,
    /// clearly horizontal rightward pull, and nothing else.
    #[test]
    fn the_back_swipe_needs_a_deliberate_rightward_pull() {
        let travel = theme::OVERLAY_BACK_SWIPE_TRAVEL;
        assert!(overlay_back_swipe_committed(travel, 0.0));
        // Anything shorter keeps the page, and the same pull leftward is not a
        // back gesture at all.
        assert!(!overlay_back_swipe_committed(travel - 1.0, 0.0));
        assert!(!overlay_back_swipe_committed(-travel, 0.0));
        // A steep diagonal belongs to the list under the finger.
        assert!(!overlay_back_swipe_committed(travel, travel));
        assert!(!overlay_back_swipe_claimed(
            theme::DRAWER_DRAG_THRESHOLD - 1.0,
            0.0
        ));
        assert!(overlay_back_swipe_claimed(
            theme::DRAWER_DRAG_THRESHOLD,
            0.0
        ));
        // The claim arms well before the commit: the page has to stop the list
        // scrolling under a gesture that is still on its way to the threshold.
        assert!(overlay_back_swipe_claimed(travel, 0.0));
        // Drift within the drawer's own ratio is tolerated; a steeper diagonal
        // belongs to the list.
        assert!(overlay_back_swipe_committed(
            travel,
            travel / theme::DRAWER_VERTICAL_CANCEL_RATIO - 1.0
        ));
        assert!(!overlay_back_swipe_committed(
            travel,
            travel / theme::DRAWER_VERTICAL_CANCEL_RATIO + 1.0
        ));
    }

