    #[test]
    fn drawer_close_animation_is_faster() {
        assert_eq!(
            drawer_snap_duration_ms(0.0, 1.0),
            theme::DRAWER_OPEN_ANIMATION_MS
        );
        assert_eq!(
            drawer_snap_duration_ms(1.0, 0.0),
            theme::DRAWER_CLOSE_ANIMATION_MS
        );
        assert_eq!(
            drawer_snap_duration_ms(0.0, -1.0),
            theme::DRAWER_OPEN_ANIMATION_MS
        );
        assert_eq!(
            drawer_snap_duration_ms(-1.0, 0.0),
            theme::DRAWER_CLOSE_ANIMATION_MS
        );
    }

    #[test]
    fn a_deliberate_flick_opens_a_drawer_from_a_short_drag() {
        let toward_sessions = DrawerVelocity::default().record(
            theme::DRAWER_SWIPE_VELOCITY,
            0.0,
            Duration::from_secs(1),
        );
        let toward_workbench = DrawerVelocity::default().record(
            -theme::DRAWER_SWIPE_VELOCITY,
            0.0,
            Duration::from_secs(1),
        );
        assert_eq!(
            drawer_snap_target(DrawerPage::Sessions, 0.05, 0.0, toward_sessions, 0.0),
            1.0
        );
        assert_eq!(
            drawer_snap_target(DrawerPage::Workbench, -0.05, 0.0, toward_workbench, 0.0),
            -1.0
        );
    }

    #[test]
    fn slow_drags_still_need_the_travel_hysteresis() {
        let slow = DrawerVelocity::default()
            .record(90.0, 0.0, Duration::from_secs(1))
            .record(90.0, 0.0, Duration::from_secs(1));
        assert!(slow.vx < theme::DRAWER_SWIPE_VELOCITY);
        assert_eq!(
            drawer_snap_target(DrawerPage::Sessions, 0.05, 0.0, slow, 0.0),
            0.0
        );
        assert_eq!(
            drawer_snap_target(DrawerPage::Sessions, 0.25, 0.0, slow, 0.0),
            1.0
        );
    }

    #[test]
    fn diagonal_flicks_do_not_commit_drawer_swipes() {
        let diagonal = DrawerVelocity::default().record(
            theme::DRAWER_SWIPE_VELOCITY,
            theme::DRAWER_SWIPE_VELOCITY,
            Duration::from_secs(1),
        );
        assert!(!diagonal.is_horizontal_flick());
        assert_eq!(
            drawer_snap_target(DrawerPage::Sessions, 0.05, 0.0, diagonal, 0.0),
            0.0
        );
    }

    #[test]
    fn an_away_flick_closes_an_open_drawer_from_any_travel() {
        let away = DrawerVelocity::default().record(
            -theme::DRAWER_SWIPE_VELOCITY,
            0.0,
            Duration::from_secs(1),
        );
        assert_eq!(
            drawer_snap_target(DrawerPage::Sessions, 0.95, 0.0, away, 1.0),
            0.0
        );
    }

    #[test]
    fn velocity_blends_recent_movement_with_a_finite_memory() {
        let fast = DrawerVelocity::default().record(2_000.0, 0.0, Duration::from_secs(1));
        // One short event at the end cannot fully erase a fast flick.
        let recovered = fast.record(50.0, 0.0, Duration::from_secs(1));
        assert!(recovered.vx.abs() > 800.0);
        assert!(fast.is_horizontal_flick());
        // A vertical component weakens the horizontal flick verdict.
        let tilted = fast.record(0.0, 2_000.0, Duration::from_secs(1));
        assert!(!tilted.is_horizontal_flick());
    }

    #[test]
    fn push_back_screen_collapses_consecutive_duplicates() {
        let mut stack: Vec<BackScreen> = Vec::new();
        let push = |stack: &mut Vec<BackScreen>, screen| {
            if stack.last() != Some(&screen) {
                stack.push(screen);
            }
        };
        push(&mut stack, BackScreen::SessionsDrawer);
        push(&mut stack, BackScreen::SessionsDrawer);
        assert_eq!(stack, vec![BackScreen::SessionsDrawer]);
        push(&mut stack, BackScreen::Overlay(MobileOverlay::Settings));
        assert_eq!(
            stack,
            vec![
                BackScreen::SessionsDrawer,
                BackScreen::Overlay(MobileOverlay::Settings)
            ]
        );
    }

    #[test]
    fn removing_a_back_screen_also_drops_entries_opened_on_top_of_it() {
        let mut stack = vec![
            BackScreen::SessionsDrawer,
            BackScreen::Overlay(MobileOverlay::Pairing),
            BackScreen::Overlay(MobileOverlay::Settings),
        ];
        while let Some(index) = stack
            .iter()
            .rposition(|screen| matches!(screen, BackScreen::Overlay(_)))
        {
            stack.truncate(index);
        }
        assert_eq!(stack, vec![BackScreen::SessionsDrawer]);
    }

    #[test]
    fn sync_back_stack_drops_stale_entries_and_keeps_the_live_overlay() {
        // Mirrors `MobileApp::sync_back_stack_with_ui`'s bookkeeping on a plain
        // stack: stale screens fall away, then the open overlay is re-armed.
        let mut stack = vec![
            BackScreen::SessionsDrawer,
            BackScreen::SessionAction,
            BackScreen::Overlay(MobileOverlay::Settings),
        ];
        let session_action_open = false;
        stack.retain(|screen| match *screen {
            BackScreen::Overlay(_) => false,
            BackScreen::SessionAction => session_action_open,
            BackScreen::RuntimeOptions => false,
            BackScreen::NewSessionPicker => false,
            BackScreen::SessionsDrawer => true,
            BackScreen::WorkbenchDrawer => true,
            BackScreen::SidebarSearch => false,
            BackScreen::SidebarBatchMode => false,
            BackScreen::TimelineFileDiff => false,
        });
        let overlay = Some(MobileOverlay::Settings);
        if let Some(overlay) = overlay
            && stack.last() != Some(&BackScreen::Overlay(overlay))
        {
            stack.push(BackScreen::Overlay(overlay));
        }
        assert_eq!(
            stack,
            vec![
                BackScreen::SessionsDrawer,
                BackScreen::Overlay(MobileOverlay::Settings)
            ]
        );
    }

    #[test]
    fn side_pages_travel_one_full_viewport() {
        let width = 390.0;
        assert_eq!(drawer_left(DrawerPage::Sessions, 0.0, width), -width);
        assert_eq!(drawer_left(DrawerPage::Sessions, 1.0, width), 0.0);
        assert_eq!(drawer_left(DrawerPage::Workbench, 0.0, width), width);
        assert_eq!(drawer_left(DrawerPage::Workbench, -1.0, width), 0.0);
    }

    #[test]
    fn timeline_follow_only_stays_active_near_the_bottom() {
        assert_eq!(timeline_distance_to_bottom(-500.0, 500.0), 0.0);
        assert_eq!(timeline_distance_to_bottom(-450.0, 500.0), 50.0);
        assert_eq!(timeline_distance_to_bottom(-100.0, 500.0), 400.0);
    }

    #[test]
    fn timeline_list_has_a_scroll_extent_before_offscreen_turns_are_measured() {
        let state = timeline_list_state(10);

        assert_eq!(state.item_count(), 10);
        assert_eq!(
            state.max_offset_for_scrollbar().y,
            px(10.0 * TIMELINE_TURN_ESTIMATED_HEIGHT_PX)
        );

        // The view resets the count in place rather than swapping in a fresh
        // state, because the state carries the older-history scroll handler.
        // The uniform height has to survive that for the extent to stay right.
        state.reset_with_uniform_height(4, px(TIMELINE_TURN_ESTIMATED_HEIGHT_PX));
        assert_eq!(state.item_count(), 4);
        assert_eq!(
            state.max_offset_for_scrollbar().y,
            px(4.0 * TIMELINE_TURN_ESTIMATED_HEIGHT_PX)
        );
    }

    /// Older history is wanted before the reader reaches the top, so the page
    /// is already there; parking at the very top must not be what triggers it.
    #[test]
    fn older_history_is_prefetched_within_a_screen_and_a_half_of_the_top() {
        // Twelve visible turns put the band at eighteen.
        assert!(timeline_viewport_is_near_top(0, 12));
        assert!(timeline_viewport_is_near_top(18, 12));
        assert!(!timeline_viewport_is_near_top(19, 12));
        // Two screens down is well past the band.
        assert!(!timeline_viewport_is_near_top(24, 12));
        // A report that saw nothing cannot say where the reader is.
        assert!(!timeline_viewport_is_near_top(0, 0));
    }

    #[test]
    fn drawer_session_metadata_stays_compact_and_readable() {
        assert_eq!(workspace_label("/work/vibex"), "vibex");
        assert_eq!(workspace_label("/work/vibex/"), "vibex");
        assert_eq!(workspace_label("C:\\work\\vibex"), "vibex");
        let locale = vibex_ui::locale::Locale::En;
        assert_eq!(session_sidebar_time_label(0), "");
        let now = chrono::Local::now().naive_local();
        assert_eq!(
            session_sidebar_time_label_at(now, now, locale),
            now.format("%H:%M").to_string()
        );
        assert_eq!(
            session_sidebar_time_label_at(
                now - chrono::Duration::days(1),
                now,
                vibex_ui::locale::Locale::ZhCn,
            ),
            "昨天"
        );
    }

    /// The drawer footer's runtime entry is a status chip: the leading dot's
    /// colour is the whole connection state, the words for it stay in the
    /// accessible name, the name takes the row, and the touch area ends with
    /// its own label instead of spanning the footer behind a disclosure arrow.
    #[test]
    fn the_drawer_footer_runtime_row_is_a_dot_and_a_name() {
        let source = include_str!("app.rs");
        let row = renderer_source(source, "render_drawer_host_row");
        // `renderer_source` runs to the next item that carries a doc comment,
        // and this helper is followed by bare accessors, so cut at the next
        // signature before asserting on what the row itself paints.
        let row = &row[..row.find("\n    fn ").unwrap_or(row.len())];
        // One line: the state is never spelled out under the name.
        assert!(!row.contains("FONT_MICRO"));
        assert!(row.contains(".bg(status.status.dot_color())"));
        assert!(row.contains(".text_ellipsis()"));
        assert!(row.contains("Self::open_pairing"));
        // A screen reader still gets the state the colour carries.
        assert!(row.contains(".aria_label(format!(\"{label} · {}\", status.label()))"));

        // The chip hugs its label rather than stretching to the footer's width;
        // the flexible wrapper is what keeps the settings button trailing.
        let chip = row
            .split_once(".id(\"mobile-host-switcher\")")
            .expect("the footer row keeps its id")
            .1;
        assert!(chip.contains(".child(label)"), "the chip shows the name");
        assert!(!chip.contains(".flex_1()"));
        assert!(row.contains(".flex_1()"));
        // Smaller than a full touch target, and no arrow into another page.
        assert!(chip.contains(".h(px(theme::DRAWER_ACTION_HEIGHT))"));
        assert!(!chip.contains(".h(px(theme::TOUCH_TARGET))"));
        assert!(!chip.contains("chevron-right.svg"));
    }

    #[gpui::test]
    fn drawer_scroll_does_not_move_the_timeline_behind_it(cx: &mut TestAppContext) {
        let drawer_scroll = UniformListScrollHandle::new();
        let observed_drawer_scroll = drawer_scroll.0.borrow().base_handle.clone();
        let timeline_scroll = gpui::ScrollHandle::new();
        let observed_timeline_scroll = timeline_scroll.clone();
        let (_, cx) = cx.add_window_view(|_, _| DrawerScrollIsolationProbe {
            drawer_scroll,
            timeline_scroll,
        });

        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(observed_drawer_scroll.max_offset().y > px(0.0));
        assert!(observed_timeline_scroll.max_offset().y > px(0.0));

        cx.simulate_event(ScrollWheelEvent {
            position: point(px(40.0), px(120.0)),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-160.0))),
            modifiers: Default::default(),
            touch_phase: TouchPhase::Moved,
        });
        cx.run_until_parked();

        assert!(observed_drawer_scroll.offset().y < px(0.0));
        assert_eq!(observed_timeline_scroll.offset().y, px(0.0));
    }

    /// The name of the function whose body contains `index`, if any.
    fn enclosing_function_name(source: &str, index: usize) -> Option<&str> {
        let head = &source[..index];
        let (_, tail) = head.rsplit_once("\nfn ")?;
        tail.split(['(', '<', ' ']).next()
    }

    /// The bracketed body of the call whose opening bracket is at `open`.
    fn call_body(source: &str, open: usize) -> &str {
        let mut depth = 0usize;
        for (offset, character) in source[open..].char_indices() {
            match character {
                '(' | '[' | '{' => depth += 1,
                ')' | ']' | '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return &source[open..open + offset];
                    }
                }
                _ => {}
            }
        }
        panic!("the call at byte {open} is never closed")
    }

    /// The statement that ends where `index` points, brackets balanced.
    ///
    /// A closing brace at depth zero closed the statement before this one:
    /// walking further back would pull an unrelated expression — and the
    /// `backend.` it names — into the statement being inspected.
    fn statement_before(source: &str, index: usize) -> &str {
        let mut depth = 0usize;
        let mut start = 0;
        for (offset, character) in source[..index].char_indices().rev() {
            match character {
                '}' if depth == 0 => {
                    start = offset + character.len_utf8();
                    break;
                }
                ')' | ']' | '}' => depth += 1,
                '(' | '[' | '{' => {
                    if depth == 0 {
                        start = offset + character.len_utf8();
                        break;
                    }
                    depth -= 1;
                }
                ';' if depth == 0 => {
                    start = offset + 1;
                    break;
                }
                _ => {}
            }
        }
        source[start..index].trim()
    }

    /// Whether the statement calls a method on `owner`, across a line break.
    ///
    /// The app writes a long call as the receiver, a newline, and the method:
    /// `backend` and its `.` are never adjacent in the source, so the search is
    /// for the name followed by whatever whitespace the formatter chose.
    fn calls_a_method_on(statement: &str, owner: &str) -> bool {
        statement.match_indices(owner).any(|(offset, _)| {
            let before = statement[..offset].chars().next_back();
            if before.is_some_and(|character| character.is_alphanumeric() || character == '_') {
                return false;
            }
            statement[offset + owner.len()..]
                .trim_start()
                .starts_with('.')
        })
    }

    /// Every backend future a GPUI task awaits itself, with its byte offset.
    ///
    /// The answer a GPUI task works on arrives from a `runner`, so an awaited
    /// statement that names the backend — or a controller, which is the same
    /// request one layer up — is a request polled on the foreground executor.
    fn backend_futures_awaited_by_gpui_tasks(source: &str) -> Vec<String> {
        // The test module quotes the very patterns this scan looks for.
        let source = source
            .split("\nmod tests {")
            .next()
            .expect("the module has production code");
        let mut found = Vec::new();
        for (spawn, _) in source.match_indices("cx.spawn(") {
            let open = spawn + "cx.spawn".len();
            let body = call_body(source, open);
            for (offset, _) in body.match_indices(".await") {
                let statement = statement_before(body, offset);
                if calls_a_method_on(statement, "backend")
                    || calls_a_method_on(statement, "controller")
                {
                    found.push(format!("byte {}: {statement}", open + offset));
                }
            }
        }
        found
    }

    /// A backend request belongs on the Tokio runtime, never on the GPUI task.
    ///
    /// `vibex-remote-client` futures build their timeouts from the Tokio
    /// context of the thread that polls them, and the GPUI foreground executor
    /// has none: a request awaited inside `cx.spawn` panics on the render
    /// thread. That panic cannot unwind out of the looper callback the platform
    /// runs main-thread work in, so Android aborts the process instead of
    /// reporting anything — the phone closed on every session switch until the
    /// command catalogue moved behind `gpui_tokio::Tokio::spawn`. A new request
    /// has to enter the same way: the GPUI task awaits its `runner`, and only
    /// the answer crosses back.
    #[test]
    fn gpui_tasks_never_poll_a_backend_future() {
        for (name, source) in [
            ("android_insets.rs", include_str!("android_insets.rs")),
            ("app.rs", include_str!("app.rs")),
            ("team.rs", include_str!("team.rs")),
            ("workbench.rs", include_str!("workbench.rs")),
        ] {
            let found = backend_futures_awaited_by_gpui_tasks(source);
            assert!(
                found.is_empty(),
                "{name}: run these requests through `gpui_tokio::Tokio::spawn` \
                 instead of polling them in the GPUI task: {found:#?}"
            );
        }
    }

    /// The guard above is only worth its keep if it sees a real violation.
    #[test]
    fn the_backend_future_guard_recognizes_a_violation() {
        let sample = r#"
fn session_opened(cx: &mut Context<Self>) {
    let task = cx.spawn(async move |entity, cx| {
        let discovery = backend
            .discover_agent_commands(AgentCommandDiscoverRequest {
                trigger: None,
                limit: Some(64),
            })
            .await;
        let _ = entity.update(cx, |_, cx| cx.notify());
    });
    let _ = task;
}
"#;

        assert_eq!(backend_futures_awaited_by_gpui_tasks(sample).len(), 1);
    }

    /// Every text field the phone renders has to ask for the keyboard on a tap.
    ///
    /// The platform shows the IME on focus changes alone, so a field that keeps
    /// focus after the user dismisses the keyboard never asks for it again; the
    /// tap has to. The kit's `Input`/`Textarea` expose no event hook, so the
    /// field's own frame carries it — never a row that also holds buttons, or a
    /// tap on a button would open the keyboard.
    #[test]
    fn every_text_field_asks_for_the_keyboard_on_a_tap() {
        for (name, source) in [
            ("app.rs", include_str!("app.rs")),
            ("workbench.rs", include_str!("workbench.rs")),
        ] {
            // The test module quotes the very patterns this test looks for.
            let source = source
                .split("\nmod tests {")
                .next()
                .expect("the module has production code");
            for field in ["Input::new(", "Textarea::new("] {
                for (index, _) in source.match_indices(field) {
                    // A leading identifier byte means this is not the kit field.
                    if source[..index]
                        .chars()
                        .next_back()
                        .is_some_and(|previous| previous.is_alphanumeric() || previous == '_')
                    {
                        continue;
                    }
                    // The shared renderers return the kit component itself; the
                    // frames that call them carry the hook.
                    if matches!(
                        enclosing_function_name(source, index),
                        Some("input_element" | "textarea_element")
                    ) {
                        continue;
                    }
                    let start = source[..index]
                        .char_indices()
                        .rev()
                        .nth(600)
                        .map_or(0, |(offset, _)| offset);
                    let frame = &source[start..index];
                    assert!(
                        frame.contains("resume_keyboard_on_tap"),
                        "{name}: the field at byte {index} has no keyboard tap hook"
                    );
                }
            }
        }
    }

    /// A long press on the composer has to reach the touch toolbar instead of
    /// the kit's context menu. The kit's menu is a popup that takes focus, and
    /// focus leaving the input is what collapses the keyboard the toolbar is
    /// positioned against, so the two halves are one decision.
    #[test]
    fn composer_long_press_opens_the_touch_selection_toolbar() {
        let source = include_str!("app.rs");
        let composer = source
            .split_once("Textarea::new(&self.composer_input)")
            .map(|(_, tail)| tail)
            .expect("the composer should still render the kit's textarea");
        let hook = composer
            .split_once("fn ")
            .map(|(body, _)| body)
            .expect("the composer's context menu hook should stay inspectable");

        assert!(hook.contains(".context_menu("));
        assert!(hook.contains("menu.open(cx)"));
        assert!(source.contains("self.selection_menu.clone()"));
    }

    /// A row is picked up by a long press, and the platform reports a touch as
    /// a pan only once the finger has travelled past its slop — so arming from
    /// the scroll stream could never fire for the stationary press the gesture
    /// is. The list has to listen for the long press itself, and the drag has
    /// to be driven by that same touch as it moves.
    #[test]
    fn the_sidebar_drag_is_armed_by_a_long_press() {
        let source = include_str!("app.rs");
        let drawer = source
            .split_once("fn render_drawer")
            .map(|(_, tail)| tail)
            .expect("the drawer should still be one renderer");
        let listener = drawer
            .split_once("move |event: &LongPressEvent")
            .map(|(_, tail)| tail)
            .expect("the drawer's row list should listen for a long press");

        assert!(listener.contains("bounds.contains(&event.position)"));
        assert!(listener.contains("on_sidebar_row_long_press"));
        assert!(
            drawer.contains(".on_scroll_wheel(cx.listener(Self::consume_drawer_scroll))"),
            "a pan over the list is a scroll, never the start of a row move"
        );

        // Both drag steps take the touch position the long press reports: a
        // scroll event carries no position once the recognizer has claimed the
        // gesture as a press.
        for function in ["fn begin_sidebar_drag", "fn advance_sidebar_drag"] {
            let body = source
                .split_once(function)
                .map(|(_, tail)| tail.split_once("\n    fn ").map_or(tail, |(body, _)| body))
                .unwrap_or_else(|| panic!("{function} should stay inspectable"));
            assert!(
                body.contains("position: Point<Pixels>"),
                "{function} should take the long press's position"
            );
        }

        let handler = source
            .split_once("fn on_sidebar_row_long_press")
            .map(|(_, tail)| tail.split_once("\n    fn ").map_or(tail, |(body, _)| body))
            .expect("the long-press handler should stay inspectable");
        assert!(handler.contains("self.begin_sidebar_drag(event.position, cx)"));
        assert!(handler.contains("self.advance_sidebar_drag(event.position, cx)"));
        assert!(handler.contains("self.finish_sidebar_drag(false, cx)"));
        assert!(handler.contains("self.finish_sidebar_drag(true, cx)"));
    }

    fn host_bundle(server_id: &str, display_name: &str) -> MobileCredentialBundle {
        let identity =
            vibex_remote_client::ClientDeviceIdentity::generate(vibex_core::DeviceId::new())
                .expect("client identity");
        MobileCredentialBundle {
            schema_version: crate::pairing::MOBILE_CREDENTIAL_SCHEMA_VERSION.to_string(),
            record: vibex_remote_client::RemoteCredentialRecord {
                server_url: "https://desktop.example".to_string(),
                auth: vibex_core::RemoteAuthProof {
                    device_id: identity.device_id().clone(),
                    auth_token: "grant".to_string(),
                },
                device_identity_public_key: identity.public_key_base64(),
                server_identity_public_key: Some("server-public".to_string()),
            },
            identity_private_key: identity.private_key_base64(),
            expected_server_id: server_id.to_string(),
            client_type: vibex_core::RemoteClientType::Mobile,
            allow_insecure_local_dev: false,
            display_name: Some(display_name.to_string()),
            route: None,
        }
    }

    /// A credential the phone refuses to build a transport for, so a probe
    /// settles without a single packet leaving the machine.
    fn unbuildable_host_bundle(server_id: &str, display_name: &str) -> MobileCredentialBundle {
        let mut bundle = host_bundle(server_id, display_name);
        // Insecure transport, and this credential is not marked as a local dev
        // runtime, so building a backend for it fails before any I/O.
        bundle.record.server_url = "http://desktop.example".to_string();
        bundle
    }

    /// Nothing is connected on the first screen, so what a saved runtime shows
    /// there is whether it answered the phone's probe: each round asks every
    /// saved runtime and forgets the ones that are gone.
    #[test]
    fn a_reachability_round_asks_every_saved_runtime_and_forgets_the_rest() {
        let mut states = BTreeMap::new();
        states.insert("runtime-gone".to_string(), HostReachability::Online);
        states.insert("runtime-a".to_string(), HostReachability::Offline);
        begin_reachability_round(
            &["runtime-a".to_string(), "runtime-b".to_string()],
            &mut states,
        );
        assert_eq!(
            states.len(),
            2,
            "only saved runtimes keep a reachability state"
        );
        assert_eq!(
            states.get("runtime-a"),
            Some(&HostReachability::Probing),
            "a runtime already answered is asked again"
        );
        assert_eq!(states.get("runtime-b"), Some(&HostReachability::Probing));
        assert!(!states.contains_key("runtime-gone"));
    }

    /// A credential the phone cannot turn into a transport is a runtime that
    /// does not answer, and asking costs nothing: no request is made.
    #[test]
    fn an_unbuildable_credential_never_probes_online() {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("probe runtime");
        let bundle = unbuildable_host_bundle("runtime-a", "runtime-a");
        assert!(!runtime.block_on(bundle.probe_online()));
    }

    /// The runtime is the authority for both names it publishes: the name it
    /// goes by and the name it holds for this phone. The published runtime name
    /// replaces the one captured at pairing, and a peer that reports neither
    /// must not erase what is already known.
    #[test]
    fn observing_a_runtime_identity_updates_the_host_entry() {
        let bundle = host_bundle("studio-desktop", "studio.local");
        let mut entry = MobileHostEntry::from_bundle(&bundle, RemoteServerKind::Unknown);
        assert_eq!(entry.display_label(), "studio.local");

        assert!(entry.observe_runtime_identity("dev", "Pixel 8"));
        assert_eq!(entry.display_label(), "dev");
        assert_eq!(entry.bundle.display_name.as_deref(), Some("dev"));
        assert_eq!(entry.device_display_name.as_deref(), Some("Pixel 8"));

        // The runtime name is unchanged and the device name is not published in
        // this report, so neither is a new persisted fact.
        assert!(!entry.observe_runtime_identity("dev", ""));
        assert_eq!(entry.device_display_name.as_deref(), Some("Pixel 8"));

        // An older peer reports no names at all: the entry keeps the label it
        // derived from its credential.
        assert!(!entry.observe_runtime_identity("", ""));
        assert_eq!(entry.display_label(), "dev");
    }

    /// Every runtime surface reads its name through `active_host_label`, so the
    /// user's rename has to win over the credential-derived label, and clearing
    /// it has to fall back.
    #[gpui::test]
    fn active_host_label_prefers_the_users_rename(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();
        app.update(cx, |app, _| {
            let bundle = host_bundle("studio-desktop", "studio.local");
            app.active_host_id = Some(bundle.host_id().to_string());
            app.known_hosts = vec![MobileHostEntry::from_bundle(
                &bundle,
                RemoteServerKind::Unknown,
            )];
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.active_host_label()),
            "studio.local"
        );

        app.update(cx, |app, _| {
            app.known_hosts[0].name_override = Some("  Studio  ".to_string());
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.active_host_label()),
            "Studio"
        );

        // An empty override is not a name: it falls back to the derived label.
        app.update(cx, |app, _| {
            app.known_hosts[0].name_override = Some("   ".to_string());
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.active_host_label()),
            "studio.local"
        );
    }

    /// The runtime surfaces are only reachable through the drawer, so a real
    /// paint is the only thing between a layout mistake and a blank screen on
    /// a device. Each page is drawn both with a paired runtime and with none.
    #[gpui::test]
    fn runtime_overlays_paint(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();
        let bundle = host_bundle("studio-desktop", "studio.local");
        app.update(cx, |app, _| {
            app.active_host_id = Some(bundle.host_id().to_string());
            app.known_hosts = vec![MobileHostEntry::from_bundle(
                &bundle,
                RemoteServerKind::Unknown,
            )];
        });

        for overlay in [
            MobileOverlay::Pairing,
            MobileOverlay::Team,
            MobileOverlay::HostActions,
            MobileOverlay::HostDetail,
            MobileOverlay::HostRename,
            MobileOverlay::HostRemove,
        ] {
            for hosts in [vec![bundle.clone()], Vec::new()] {
                app.update(cx, |app, _| {
                    app.overlay = Some(overlay);
                    app.host_overlay_target = Some("studio-desktop".to_string());
                    app.known_hosts = hosts
                        .iter()
                        .map(|bundle| {
                            MobileHostEntry::from_bundle(bundle, RemoteServerKind::Unknown)
                        })
                        .collect();
                });
                cx.update(|window, cx| {
                    let _ = window.draw(cx);
                });
            }
        }

        // The drawer footer shows the same status and is the entry point to all
        // of the above, so it is painted with the list open too.
        app.update(cx, |app, cx| {
            app.overlay = None;
            app.host_overlay_target = None;
            app.known_hosts = vec![MobileHostEntry::from_bundle(
                &bundle,
                RemoteServerKind::Unknown,
            )];
            app.active_host_id = Some(bundle.host_id().to_string());
            app.start_drawer_snap(DrawerPage::Sessions.open_offset(), None, cx);
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
    }

    /// The transport has twelve states and the phone shows eight; every one of
    /// them must land on a status that has words to show beside its dot.
    #[test]
    fn every_transport_state_maps_to_one_runtime_status() {
        let cases = [
            (RemoteConnectionState::Idle, RuntimeStatus::Connecting),
            (RemoteConnectionState::Resolving, RuntimeStatus::Connecting),
            (RemoteConnectionState::Probing, RuntimeStatus::Connecting),
            (RemoteConnectionState::Connecting, RuntimeStatus::Connecting),
            (
                RemoteConnectionState::Authenticating,
                RuntimeStatus::Connecting,
            ),
            (RemoteConnectionState::Syncing, RuntimeStatus::Connecting),
            (RemoteConnectionState::Online, RuntimeStatus::Connected),
            (RemoteConnectionState::Degraded, RuntimeStatus::Unstable),
            (
                RemoteConnectionState::Reconnecting,
                RuntimeStatus::Reconnecting,
            ),
            (RemoteConnectionState::Offline, RuntimeStatus::Offline),
            (RemoteConnectionState::Revoked, RuntimeStatus::Revoked),
            (
                RemoteConnectionState::Incompatible,
                RuntimeStatus::Incompatible,
            ),
        ];
        for (state, expected) in cases {
            let status = RuntimeStatus::from_connection_state(state);
            assert_eq!(status, expected, "{state:?}");
            assert!(!status.label(1).is_empty(), "{state:?}");
        }
        // A non-active runtime is never reported as live, and the reconnect
        // attempt is only worth naming once there has been more than one.
        assert_eq!(
            RuntimeStatusView::inactive().status,
            RuntimeStatus::NotConnected
        );
        assert!(RuntimeStatus::Reconnecting.label(3).contains('3'));
        assert!(!RuntimeStatus::Reconnecting.label(1).contains('1'));
    }

    /// The detail page's type field is the only place the phone explains what
    /// the peer is; an unreported kind must keep the generic runtime copy.
    #[test]
    fn runtime_kind_labels_are_localized_and_unknown_stays_generic() {
        use vibex_ui::locale::Locale;

        for locale in [Locale::En, Locale::ZhCn, Locale::ZhTw] {
            assert_eq!(
                host_kind_label_for(locale, RemoteServerKind::Unknown),
                locale::common_for(locale, "Runtime"),
                "{locale:?}"
            );
            // The generic copy is what every locale already showed, so a peer
            // that never reported its kind renders exactly as before.
            assert!(!host_kind_label_for(locale, RemoteServerKind::Unknown).is_empty());
        }
        assert_eq!(
            host_kind_label_for(Locale::En, RemoteServerKind::Desktop),
            "Desktop"
        );
        assert_eq!(
            host_kind_label_for(Locale::En, RemoteServerKind::Headless),
            "Headless server"
        );
        assert_eq!(
            host_kind_label_for(Locale::ZhCn, RemoteServerKind::Desktop),
            "桌面端"
        );
        assert_eq!(
            host_kind_label_for(Locale::ZhCn, RemoteServerKind::Headless),
            "无头服务器"
        );
        assert_eq!(
            host_kind_label_for(Locale::ZhTw, RemoteServerKind::Desktop),
            "桌面版"
        );
        assert_eq!(
            host_kind_label_for(Locale::ZhTw, RemoteServerKind::Headless),
            "無頭伺服器"
        );
        // Every kind resolves through all three locale arms rather than
        // sharing one string, so no arm can silently fall back to English.
        for kind in [
            RemoteServerKind::Desktop,
            RemoteServerKind::Headless,
            RemoteServerKind::Unknown,
        ] {
            let labels = [
                host_kind_label_for(Locale::En, kind),
                host_kind_label_for(Locale::ZhCn, kind),
                host_kind_label_for(Locale::ZhTw, kind),
            ];
            assert!(
                labels.iter().all(|label| !label.is_empty()),
                "{kind:?} has an empty label"
            );
            assert!(
                labels[0] != labels[1] && labels[1] != labels[2] && labels[0] != labels[2],
                "{kind:?} shares copy between locales: {labels:?}"
            );
        }
    }

    /// A claim route that cannot report the peer's kind must not erase one an
    /// earlier claim or connect learned, while a claim that does report one
    /// replaces it. Re-pairing over an offer link is the case that matters.
    #[gpui::test]
    fn remembering_a_host_never_downgrades_a_known_kind(cx: &mut TestAppContext) {
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx)
        });
        cx.run_until_parked();
        let bundle = host_bundle("studio-desktop", "studio.local");

        app.update(cx, |app, _| {
            app.remember_host(&bundle, RemoteServerKind::Desktop);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.known_hosts[0].server_kind),
            RemoteServerKind::Desktop
        );

        app.update(cx, |app, _| {
            app.remember_host(&bundle, RemoteServerKind::Unknown);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.known_hosts[0].server_kind),
            RemoteServerKind::Desktop
        );

        app.update(cx, |app, _| {
            app.remember_host(&bundle, RemoteServerKind::Headless);
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.known_hosts[0].server_kind),
            RemoteServerKind::Headless
        );
    }

    /// A rename sheet exists to be typed into: opening it must hand the caret to
    /// its field, otherwise the first keystroke goes nowhere until the user taps
    /// the input a second time.
    #[gpui::test]
    fn host_rename_sheet_opens_with_its_field_focused(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.mode = RootMode::Workspace;
            app
        });
        cx.run_until_parked();

        let bundle = host_bundle("studio-desktop", "studio.local");
        let host_id = cx.update(|window, cx| {
            app.update(cx, |app, cx| {
                app.remember_host(&bundle, RemoteServerKind::Desktop);
                let host_id = app.known_hosts[0].id.clone();
                // The field is seeded with the runtime's name, so a rename
                // starts from what the sheet is actually renaming.
                app.known_hosts[0].name_override = Some("studio".to_string());
                app.host_overlay_target = Some(host_id.clone());
                app.open_host_rename(&noop_mouse_up(), window, cx);
                host_id
            })
        });
        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::HostRename),
            "the rename sheet should be the open overlay for {host_id}"
        );

        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        let (focused, value) = cx.update(|window, cx| {
            let input = app.read(cx).host_name_input.clone();
            let input = input.read(cx);
            (
                input.focus_handle(cx).is_focused(window),
                input.value().to_string(),
            )
        });
        assert_eq!(value, "studio", "the sheet should seed its field");
        assert!(
            focused,
            "the rename field should own the caret when the sheet opens"
        );
    }

    fn update_test_release(artifact: bool) -> vibex_app_update::UpdateRelease {
        vibex_app_update::UpdateRelease {
            version: semver::Version::new(0, 2, 0),
            tag: "v0.2.0".to_string(),
            published_at: "2026-01-01T00:00:00Z".to_string(),
            notes_url: url::Url::parse("https://github.com/vibex-ai/vibex/releases/tag/v0.2.0")
                .expect("release page URL"),
            artifact: artifact.then(|| vibex_app_update::UpdateArtifact {
                os: "android".to_string(),
                arch: "arm64".to_string(),
                package: "apk".to_string(),
                install_mode: vibex_app_update::InstallMode::SystemInstaller,
                url: url::Url::parse(
                    "https://github.com/vibex-ai/vibex/releases/download/v0.2.0/vibex-0.2.0-android-arm64.apk",
                )
                .expect("artifact URL"),
                size: 12 * 1024 * 1024,
                sha256: "0".repeat(64),
                sha512: None,
            }),
            notes: None,
        }
    }

    #[test]
    fn update_cards_expose_the_state_the_user_acts_on() {
        assert!(
            update_card_model(&UpdateState::Idle).is_none(),
            "an idle updater has nothing to install"
        );
        assert!(
            update_card_model(&UpdateState::Checking).is_none(),
            "a check in flight has nothing to install yet"
        );

        let available = update_card_model(&UpdateState::Available {
            release: update_test_release(true),
        })
        .expect("an available release shows a card");
        assert_eq!(available.primary, Some(UpdateCardAction::Download));
        assert!(
            available.download_url.ends_with("-android-arm64.apk"),
            "the manual path opens the signed package"
        );
        assert_eq!(available.progress, None);
        assert!(
            available.detail.contains("12.0 MB"),
            "the card states the download size: {}",
            available.detail
        );

        let downloading = update_card_model(&UpdateState::Downloading {
            release: update_test_release(true),
            downloaded_bytes: 3 * 1024 * 1024,
            total_bytes: 12 * 1024 * 1024,
        })
        .expect("a download in flight keeps the card");
        assert_eq!(downloading.primary, None, "a download cannot be restarted");
        assert_eq!(downloading.progress, Some(0.25));

        let staged = update_card_model(&UpdateState::Staged {
            release: update_test_release(true),
            path: PathBuf::from("/data/files/updates/0.2.0/vibex-0.2.0-android-arm64.apk"),
        })
        .expect("a staged package keeps the card");
        assert_eq!(
            staged.primary,
            Some(UpdateCardAction::Install(PathBuf::from(
                "/data/files/updates/0.2.0/vibex-0.2.0-android-arm64.apk"
            )))
        );

        // A manifest without an Android artifact still has a release page, so
        // the card falls back to it instead of offering a download.
        let unsupported = update_card_model(&UpdateState::Unsupported {
            release: update_test_release(false),
            reason: "no package".to_string(),
        })
        .expect("an unsupported release still shows the page");
        assert_eq!(unsupported.primary, None);
        assert_eq!(
            unsupported.download_url,
            "https://github.com/vibex-ai/vibex/releases/tag/v0.2.0"
        );
    }

    #[gpui::test]
    fn an_available_update_offers_both_install_paths_in_settings(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            // The host test runs the Android layout by hand: only Android
            // carries the updater.
            app.update_supported = true;
            app.update_available = true;
            app.update_snapshot = Some(vibex_app_update::UpdateSnapshot {
                state: UpdateState::Available {
                    release: update_test_release(true),
                },
                ..vibex_app_update::UpdateSnapshot::default()
            });
            app.open_settings(&noop_mouse_up(), window, cx);
            app
        });
        cx.run_until_parked();
        app.update(cx, |app, cx| {
            app.settings_scroll.scroll_to_bottom();
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        // The phone is still on the pairing page: an update must be installable
        // before the first desktop is paired, which is why Settings renders
        // there too.
        for selector in [
            "mobile-settings-update-card",
            "mobile-settings-update-install",
            "mobile-settings-update-page",
        ] {
            assert!(
                cx.debug_bounds(selector).is_some(),
                "{selector} should be visible in About"
            );
        }
        assert_eq!(
            app.read_with(cx, |app, _| app.update_snapshot.as_ref().map(|snapshot| {
                matches!(snapshot.state, UpdateState::Available { .. })
            })),
            Some(true)
        );
        // Both ways out are visible: the in-app install and the browser page.
        let card = cx
            .debug_bounds("mobile-settings-update-card")
            .expect("card bounds");
        let install = cx
            .debug_bounds("mobile-settings-update-install")
            .expect("install button bounds");
        let page = cx
            .debug_bounds("mobile-settings-update-page")
            .expect("download page button bounds");
        assert!(card.contains(&install.center()));
        assert!(card.contains(&page.center()));
    }

    #[gpui::test]
    fn an_update_notification_tap_opens_the_settings_card(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            app.update_supported = true;
            app.update_available = true;
            app.update_snapshot = Some(vibex_app_update::UpdateSnapshot {
                state: UpdateState::Available {
                    release: update_test_release(true),
                },
                ..vibex_app_update::UpdateSnapshot::default()
            });
            app
        });
        cx.run_until_parked();

        // The platform reports the tap with no window borrow, exactly like the
        // stream task does.
        // The platform reports the tap on the foreground executor, exactly like
        // the stream task does.
        let entity = app.update(cx, |_, cx| cx.weak_entity());
        cx.spawn(|cx| async move {
            cx.update(|cx| open_update_surface(&entity, cx));
        })
        .detach();
        cx.run_until_parked();

        assert_eq!(
            app.read_with(cx, |app, _| app.overlay),
            Some(MobileOverlay::Settings),
            "the notification tap lands on the update card"
        );
    }

    #[gpui::test]
    fn about_names_the_update_state_without_a_verification_key(cx: &mut TestAppContext) {
        cx.update(bind_keys);
        init_kit_globals(cx);
        let data_dir = tempfile::tempdir().expect("temporary mobile data directory");
        let (app, cx) = cx.add_window_view(|window, cx| {
            theme::apply_component_theme(Some(window), cx);
            window.set_rem_size(gpui_component::Theme::global(cx).font_size);
            let mut app = MobileApp::new_for_test(data_dir.path().to_path_buf(), window, cx);
            // An Android build compiled without the release verification key.
            app.update_supported = true;
            app.open_settings(&noop_mouse_up(), window, cx);
            app
        });
        cx.run_until_parked();
        // About is its own page now, so the rows are one tap in.
        click_mobile_control(cx, "mobile-settings-about");
        cx.run_until_parked();
        app.update(cx, |app, cx| {
            app.settings_scroll.scroll_to_bottom();
            cx.notify();
        });
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        for selector in ["mobile-settings-version", "mobile-settings-update-check"] {
            assert!(
                cx.debug_bounds(selector).is_some(),
                "{selector} should be visible in About"
            );
        }
        assert!(
            cx.debug_bounds("mobile-settings-update-card").is_none(),
            "a build that cannot verify a release shows no card"
        );
    }

